window.DESIGNS = {"book-index-tiering": {"goal": {"name": "book-index-tiering", "title": "book-index.md gains a nano tier, and full-book loading stops being unconditional", "created": "2026-08-25", "outcome": "book-index.md offers nano, mini, and full tiers for all 14 vendored books, with a 3-nano-minimum judgment-gated escalation rule; Review/Maintenance's mandatory 14-file security corpus load gets the same cheap-signal-before-expensive-read shape, opposite default bias, no vendoring.", "done_when": ["books/README.md's manifest lists nano.md, mini.md, and full.md for each of the 14 books", "book-index.md states the 3-nano-minimum, judgment-gated escalation rule, replacing the prior 1-primary-plus-1-companion cap for book loading", "design-mode.md's Stage 1/3 grounding section and the architecture skill's Review/Maintenance corpus-to-book escalation both reference the new rule", "SKILL.md's Review mode security corpus step reads the first ~30 lines of all 14 security files unconditionally, then reads a file's remainder in full unless its summary clearly rules out applicability, defaulting to full on ambiguity"], "abort_if": [], "min_work": {"derived_from": "1 district (skills), 2 colliding ADRs (ADR-0015, ADR-0017), 2 boundary rules (book-index.md's prior 1+1 cap, Review mode's mandatory-14-file security rule)", "alternatives_explored": 7, "boundary_rules_checked": true, "challenge_stage_run": true}, "limits": {"warn_after_rounds": 3, "cutoff_rounds": 6}, "epics": [{"id": "E1", "slug": "book-index-tiering", "branch": "design/book-index-tiering", "pr": 16, "state": "open", "outcome": "book-index.md, books/README.md, design-mode.md, and SKILL.md's Review mode security corpus step all reflect ADR-0021's two escalation rules (book tiering, and the security corpus applicability read)"}], "stage": "review", "supersedes": null, "adr": "ADR-0021", "adrs": ["ADR-0021"], "rounds": [{"n": 1, "changed": false, "feedback_class": "approved"}, {"n": 2, "changed": true, "feedback_class": "material", "note": "Folded in the security corpus applicability read after a live discussion of whether the mandatory 14-file security load deserved the same scrutiny as book loading; resolved with an opposite default bias (full-on-ambiguity, not skip-on-ambiguity)."}]}, "intent": {"problem": "book-index.md's escalation goes straight from the Tier 1 corpus heuristic to one full vendored book, 300-1000 lines. Upstream ciembor/agent-rules-books has since published nano (about 20-40 lines) and mini (about 80-150 lines) tiers for the same 14 books, and books/README.md's manifest still only vendors full. Nothing in this plugin uses the smaller tiers. Separately, books/README.md documents a scripts/sync-books.sh drift-check script that does not exist anywhere in the repository.", "approach": "Vendor nano.md and mini.md alongside the existing full.md for each of the 14 books, as separate files (42 total). Change book-index.md's escalation rule: after Tier 1 narrows candidates, load a minimum of three nano-tier excerpts, then escalate any one of those books to mini or full only when its principles are judged to matter for the task at hand. Full-tier loading is never unconditional. Rewrite the existing 'one primary book plus one optional companion' cap to state this new ceiling explicitly. Applies to Design mode's Stage 1 (Ground) and Stage 3 (Explore) grounding, and to Review/Maintenance mode's corpus-to-book escalation. Addendum: Review/Maintenance's mandatory 14-file security corpus load gets the same cheap-signal-before-expensive-read shape, with no vendoring (the existing YAML files already separate a metadata-plus-summary block, ~17-24 lines, from worked examples). Read the first ~30 lines of all 14 unconditionally, every run, never skipping a category's summary; read a file's remainder in full unless the summary clearly rules out applicability, defaulting to full on ambiguity — the opposite bias from book escalation, because a missed security finding is worse than a wasted read.", "alternatives": [{"option": "3 nanos, then always the full book, unconditionally (the engineer's original approach)", "rejected_because": "Making the full-book read unconditional defeats the reason a cheap tier exists, and it silently breaks the existing 1+1 cap with no stated replacement."}, {"option": "Signed evidence ledger gating the full-book read behind three committed nano entries", "rejected_because": "Solves an auditability problem nobody named. Adds a new shim and file surface without reducing token cost or file count."}, {"option": "Content-addressed cold storage with per-session materialization and LRU eviction", "rejected_because": "Sized for a corpus of 140+ books; this repo vendors 14. Conflicts with the plugin family's vendor-in-tree convention (ADR-0017)."}, {"option": "Live-fetch the nano tier from upstream URLs at task time instead of vendoring it", "rejected_because": "The frame that proposed this was blocked by a security classifier. Fetching remote content into prompt context at runtime is an injection and supply-chain risk this plugin family's self-only design avoids."}, {"option": "Pre-concatenated per-book ladder file with a stop-early marker", "rejected_because": "Scored highest with the critic and collapses vendoring back to 14 files, but its stop-early discipline has no mechanical consumer. This repo's own CLAUDE.md names exactly this failure mode from the Gate 4b history."}, {"option": "Ad hoc subagent fan-out, one Task-tool call per book, verdict-only return", "rejected_because": "ADR-0015 fixes the install surface at no agents, hooks, or MCP servers. The pattern could only ever run as an in-turn call, never shipped infrastructure, and was declined even in that form to keep this design's scope to the vendored-file mechanism."}, {"option": "Panic-grep pre-filter: one hand-written panic line per nano file, grepped before any tier loads", "rejected_because": "The critic's starred non-obvious survivor, and the only option that stays inside the existing cap unmodified. Deferred rather than bundled in, since it is orthogonal to the chosen mechanism."}, {"option": "Judgment-gate the security corpus the same symmetric way as book escalation (skip-on-ambiguity)", "rejected_because": "A missed security finding in a compliance-weighted report is a worse failure than a design session under-reading one book. Security is already the highest-weighted category in the scoring rubric. The chosen rule keeps a mandatory summary read for every category and defaults to full on ambiguity instead."}], "authorship": "agent-generated", "captured": "2026-08-25", "design_name": "book-index-tiering", "out_of_scope": ["Fixing or creating scripts/sync-books.sh", "Re-vendoring the existing full/ books against upstream's current commit", "The panic-grep pre-filter and the subagent fan-out pattern, both declined for this design", "Vendoring separate nano/mini files for the security corpus — it uses a same-file partial read instead, since each YAML already separates metadata/summary from examples"], "reviewer_focus": ["Whether the judgment-gated escalation language in book-index.md is specific enough to actually change agent behavior, or vague enough to be silently ignored", "Whether the rewritten cap conflicts with any other reference file that still assumes the old 1+1 cap", "Whether the security corpus's opposite default bias (full-on-ambiguity) is stated clearly enough that a session doesn't quietly collapse it into the same skip-on-ambiguity behavior as book escalation"], "risks": ["The judgment gate ('escalate to mini/full only when it matters') has no mechanical enforcement. This repo's own Gate 4b history shows an unenforced step tends to erode under time pressure.", "Vendoring surface triples from 14 files to 42, while the sync pipeline that would check them against upstream (scripts/sync-books.sh) is already missing.", "The security corpus applicability read also has no mechanical enforcement. Its default-to-full bias on ambiguity is meant to make a false 'not applicable' verdict less likely, not impossible."], "source": "design", "testing": "No code changes; this design writes docs/ artifacts only. Verification is: book-index.md's escalation rule reads unambiguously, and the new cap language explicitly supersedes the old 1+1 cap rather than leaving both stated at once.", "unknowns": ["Whether upstream's nano/mini files exist for all 14 currently-vendored books at a syncable commit — not verified in this design"], "why_now": "The escalation ladder is missing two rungs that upstream already provides for free. Every task that reaches Tier 2 today pays the full-book cost with no cheaper option available first."}, "assessment": {"verdict": "concerns", "findings": [{"kind": "prediction", "question": "sensible", "citation": "district:skills", "text": "The approach solves the stated problem: the escalation ladder currently skips two tiers upstream already publishes. The problem belongs in the skills district, where book-index.md already lives, not in a new seam."}, {"kind": "prediction", "question": "maintainability", "constraint_introduced": "A design or review-mode session must load a minimum of three nano-tier book excerpts before it may escalate any one book to mini or full tier. Full-tier loading is judgment-gated per book, never unconditional.", "text": "This establishes a real invariant on book-index.md's own escalation rule, replacing the prior 1-primary-plus-1-companion cap for book loading specifically."}, {"kind": "prediction", "question": "new_pattern_or_duplicate", "verdict_detail": "new_pattern", "citation": "district:skills", "text": "No ADR or existing file in docs/architecture/adr/ or inventory.yaml covers tiered reference-doc escalation today. This is a new pattern for this repo, not a duplicate or reinvention."}], "captured": "2026-08-25", "regret_risk": "Judgment-gated escalation has no mechanical check. This repo's own CLAUDE.md names exactly this failure mode from the Gate 4b history: a process step with no mechanical consumer gets skipped, however well it is documented. If that happens here, the 42-file vendoring cost is paid while sessions silently keep reading only full, the same as today, and the nano/mini tiers sit unread.", "stage": "design"}, "narrative": {"landscape": {"tagline": "Three cheap reads before one expensive one.", "narration": "book-index.md picks one book to load per task, and today it only owns one size: the full one. Upstream already publishes two smaller ones. This design wires them in."}, "problem_solution": {"problem": "book-index.md's escalation jumps straight from a cheap corpus heuristic to a 300-1000 line full book. Upstream ciembor/agent-rules-books now ships nano and mini tiers for the same 14 books, and none of them are vendored or used here.", "solution": "Vendor nano.md and mini.md alongside each book's existing full.md. Require a minimum of three nano loads before any book may be judgment-escalated to mini or full, and make full-tier loading conditional instead of automatic.", "narration": "The fix is not a bigger corpus. It is using the sizes that already exist instead of reaching for the biggest one every time.", "beats": [{"kind": "grounding", "text": "Grounding found the escalation policy itself violates its own stated cap, and a documented sync script that was never actually written."}, {"kind": "divergence", "text": "Six divergent frames produced a ledger, a cold-storage index, a subagent-fan-out pattern, a live-fetch approach that a security classifier blocked outright, a pre-concatenated ladder file, and a panic-grep pre-filter."}, {"kind": "challenge", "text": "The critic scored the ladder file highest, then flagged that its own stop-early discipline has no mechanical enforcement — the same failure mode this repo's Gate 4b history already lived through. The engineer chose to accept that same risk in a simpler, separate-files form instead of adopting the ladder file's mechanism."}, {"kind": "decision", "text": "3 nanos minimum, judgment-gated escalation to mini or full, separate files per tier, the old 1+1 cap rewritten to say so explicitly."}, {"kind": "addendum", "text": "Answering a follow-up question about Review mode's mandatory 14-file security corpus load surfaced the same shape of problem — 2179 lines read unconditionally, every run, larger than a single full book. The fix folded into this design instead of spawning a new one: read each file's first ~30 lines (metadata plus summary, already structurally separate from its examples) unconditionally, then read the remainder in full unless the summary clearly rules out applicability — defaulting to full, not to skipping, on ambiguity. The opposite bias from book escalation, deliberately, because a missed security finding costs more than a wasted read."}], "alternatives": [{"option": "3 nanos, then always the full book, unconditionally", "rejected_because": "Defeats the point of a cheap tier, and breaks the existing cap with no replacement stated."}, {"option": "Signed evidence ledger", "rejected_because": "Solves auditability, a problem nobody named, at the cost of a new file surface."}, {"option": "Content-addressed cold storage", "rejected_because": "Sized for 140+ books; this repo has 14."}, {"option": "Live-fetch from upstream URLs at task time", "rejected_because": "Blocked by a security classifier — a real injection and supply-chain risk."}, {"option": "Pre-concatenated ladder file with a stop-early marker", "rejected_because": "Scored highest, but its stop-early rule has no mechanical consumer."}, {"option": "Ad hoc subagent fan-out", "rejected_because": "Would need to ship as an agent, which ADR-0015 forbids."}, {"option": "Panic-grep pre-filter", "rejected_because": "The critic's starred survivor, deferred rather than bundled into this design."}, {"option": "Judgment-gate the security corpus the same symmetric way as books (skip-on-ambiguity)", "rejected_because": "A missed finding in a compliance-weighted report costs more than a wasted read; security stays biased toward reading in full."}]}, "architecture": {"narration": "book-index.md becomes the single owner of a three-tier vendored shelf, with an explicit, stated ceiling on how much of it any one task may read. The security corpus gets the same shape of gate without a new file format.", "beats": [{"kind": "component", "text": "references/books/<name>/{nano,mini,full}.md — 42 files, replacing the current 14 full-only files."}, {"kind": "rule", "text": "book-index.md: load a minimum of 3 nano excerpts; escalate any one book to mini or full only when its principles are judged to matter; full is never automatic."}, {"kind": "consumer", "text": "Design mode Stage 1 (Ground) and Stage 3 (Explore), and Review/Maintenance's corpus-to-book escalation, both read the new rule instead of the old 1+1 cap."}, {"kind": "rule", "text": "SKILL.md's Review mode security step: read the first ~30 lines of all 14 security corpus files unconditionally; read a file's remainder in full unless its summary clearly rules out applicability; ambiguity defaults to full, not to skipping."}]}}, "diagrams": {"1": "C4Container\n    title ADR-0021 book-index.md tiering: nano, mini, full escalation\n\n    Person(session, \"Design or Review/Maintenance session\", \"Reads book-index.md through its own Read tool calls\")\n\n    Container_Boundary(t1, \"Tier 1 (unchanged)\") {\n        Container(corpus, \"corpus-index.md\", \"vendored YAML + markdown\", \"Cheap heuristic; narrows candidate books before any book file is read\")\n    }\n\n    Container_Boundary(t2, \"Tier 2 - book-index.md (this design)\") {\n        Container(index, \"book-index.md\", \"vendored markdown\", \"Escalation rule: load minimum 3 nano excerpts, then judgment-gate mini/full per book. Replaces the old 1-primary-plus-1-companion cap\")\n        Container(books, \"references/books/<name>/{nano,mini,full}.md\", \"42 vendored files, 14 books\", \"Three tiers per book: nano ~20-40 lines, mini ~80-150 lines, full 300-1000 lines\")\n    }\n\n    Container_Boundary(consumers, \"Consumers of the escalation rule\") {\n        Container(design_stage, \"design-mode.md Stage 1 (Ground) / Stage 3 (Explore)\", \"reference\", \"Grounds and explores using book-index.md's tiered rule\")\n        Container(review_stage, \"Review/Maintenance corpus-to-book escalation\", \"architecture skill mode\", \"Escalates from corpus-index.md through book-index.md; separate mandatory 14-file security corpus load is untouched by this design\")\n    }\n\n    Rel(session, corpus, \"Consults first\", \"Tier 1 heuristic\")\n    Rel(corpus, index, \"Narrows candidate books, hands off to\")\n    Rel(design_stage, index, \"Invokes escalation rule\")\n    Rel(review_stage, index, \"Invokes escalation rule\")\n    Rel(index, books, \"Loads >= 3 nano, then judgment-gated mini/full per book\")\n", "2": "sequenceDiagram\n    participant Session as Design-mode session (Stage 1: Ground)\n    participant Corpus as corpus-index.md\n    participant Index as book-index.md\n    participant BookA as clean-architecture (nano/mini/full)\n    participant BookB as domain-driven-design-distilled (nano/mini/full)\n    participant BookC as refactoring (nano/mini/full)\n\n    Session->>Corpus: Consult Tier 1 heuristic for the task\n    Corpus-->>Session: Narrows candidates to 3 books (A, B, C)\n    Session->>Index: Escalate per new rule (ADR-0021)\n\n    Index->>BookA: Read nano.md (~20-40 lines)\n    BookA-->>Index: Excerpt returned\n    Index->>BookB: Read nano.md (~20-40 lines)\n    BookB-->>Index: Excerpt returned\n    Index->>BookC: Read nano.md (~20-40 lines)\n    BookC-->>Index: Excerpt returned\n\n    Note over Index: Minimum of 3 nano loads satisfied.\\nJudge each book's principles against the task.\n\n    Index->>Index: Judge Book A's principles matter for this task\n    Index->>BookA: Escalate - read mini.md or full.md\n    BookA-->>Index: Deeper tier content returned\n\n    Index->>Index: Judge Book B's principles do not clear the bar\n    Note over Index,BookB: Book B stays at nano tier. No further Read call.\n\n    Index->>Index: Judge Book C's principles do not clear the bar\n    Note over Index,BookC: Book C stays at nano tier. No further Read call.\n\n    Index-->>Session: Grounding = 3 nanos + 1 escalated book (A)\n", "3": "classDiagram\n    class Book {\n        +name string\n        +nanoPath string\n        +miniPath string\n        +fullPath string\n        +tierLoaded Tier\n        +escalated bool\n    }\n\n    class Tier {\n        <<enumeration>>\n        NANO\n        MINI\n        FULL\n    }\n\n    class EscalationRule {\n        +minNanoLoads int = 3\n        +escalationMode string = \"judgment-gated\"\n        +cap string = \"supersedes prior 1-primary-plus-1-companion cap\"\n        +selectCandidates(corpusResult) Book[]\n        +loadNano(book) void\n        +judgePrinciplesMatter(book, task) bool\n        +escalate(book, targetTier) void\n    }\n\n    class CorpusIndex {\n        +narrowCandidates(task) Book[]\n    }\n\n    class BookIndex {\n        +rule EscalationRule\n        +run(task) GroundingResult\n    }\n\n    class GroundingResult {\n        +nanoOnlyBooks Book[]\n        +escalatedBooks Book[]\n    }\n\n    CorpusIndex --> BookIndex : hands off narrowed candidates\n    BookIndex --> EscalationRule : applies\n    EscalationRule --> Book : loads/escalates\n    Book --> Tier : tierLoaded\n    BookIndex --> GroundingResult : produces\n\n    note for Book \"escalated=false -> nano-only for rest of task\\nescalated=true -> mini or full, judgment-gated per book\"\n    note for EscalationRule \"Full-tier loading is never unconditional.\\nApplies to Design Stage 1/Stage 3 and\\nReview/Maintenance corpus-to-book escalation.\\nDoes NOT apply to the separate mandatory\\n14-file security corpus load.\"\n"}, "pr_draft": "## Problem\n\n`book-index.md`'s escalation goes straight from the Tier 1 corpus heuristic\nto one full vendored book, 300-1000 lines. Upstream\n`ciembor/agent-rules-books` has since published `nano` (about 20-40 lines)\nand `mini` (about 80-150 lines) tiers for the same 14 books, and\n`books/README.md`'s manifest still only vendors `full`. Nothing in this\nplugin uses the smaller tiers. Separately, `books/README.md` documents a\n`scripts/sync-books.sh` drift-check script that does not exist anywhere in\nthe repository.\n\nThe escalation ladder is missing two rungs that upstream already provides\nfor free. Every task that reaches Tier 2 today pays the full-book cost with\nno cheaper option available first.\n\n## Why this approach\n\nVendor `nano.md` and `mini.md` alongside the existing `full.md` for each of\nthe 14 books, as separate files (42 total). Change `book-index.md`'s\nescalation rule: after Tier 1 narrows candidates, load a minimum of three\nnano-tier excerpts, then escalate any one of those books to mini or full\nonly when its principles are judged to matter for the task at hand.\nFull-tier loading is never unconditional. Rewrite the existing \"one primary\nbook plus one optional companion\" cap to state this new ceiling explicitly.\nApplies to Design mode's Stage 1 (Ground) and Stage 3 (Explore) grounding,\nand to Review/Maintenance mode's corpus-to-book escalation.\n\n**Addendum.** Review/Maintenance's mandatory 14-file security corpus load\ngets the same cheap-signal-before-expensive-read shape, with no vendoring:\neach YAML already separates its metadata-plus-summary block (~17-24 lines)\nfrom its worked examples. Read the first ~30 lines of all 14\nunconditionally, every run, never skipping a category's summary; read a\nfile's remainder in full unless the summary clearly rules out\napplicability, defaulting to full on ambiguity — the opposite bias from\nbook escalation, because a missed security finding costs more than a\nwasted read.\n\n## Alternatives considered\n\n- **3 nanos, then always the full book, unconditionally (the engineer's\n  original approach)** — rejected because making the full-book read\n  unconditional defeats the reason a cheap tier exists, and it silently\n  breaks the existing 1+1 cap with no stated replacement.\n- **Signed evidence ledger gating the full-book read behind three\n  committed nano entries** — rejected because it solves an auditability\n  problem nobody named, and adds a new shim and file surface without\n  reducing token cost or file count.\n- **Content-addressed cold storage with per-session materialization and\n  LRU eviction** — rejected because it is sized for a corpus of 140+\n  books; this repo vendors 14. Conflicts with the plugin family's\n  vendor-in-tree convention (ADR-0017).\n- **Live-fetch the nano tier from upstream URLs at task time** — rejected\n  because the frame that proposed this was blocked by a security\n  classifier. Fetching remote content into prompt context at runtime is an\n  injection and supply-chain risk this plugin family's self-only design\n  avoids.\n- **Pre-concatenated per-book ladder file with a stop-early marker** —\n  rejected because its stop-early discipline has no mechanical consumer.\n  This repo's own CLAUDE.md names exactly this failure mode from the\n  Gate 4b history, even though this option scored highest with the critic.\n- **Ad hoc subagent fan-out, one Task-tool call per book, verdict-only\n  return** — rejected because ADR-0015 fixes the install surface at no\n  agents, hooks, or MCP servers, and the pattern was declined even as an\n  in-turn call to keep this design's scope to the vendored-file mechanism.\n- **Panic-grep pre-filter** — rejected for this design's scope, though it\n  is the critic's starred non-obvious survivor and the only option that\n  stays inside the existing cap unmodified. Deferred, not disqualified.\n- **Judgment-gate the security corpus the same symmetric way as book\n  escalation (skip-on-ambiguity)** — rejected because a missed security\n  finding in a compliance-weighted report is a worse failure than a design\n  session under-reading one book. Security stays biased toward reading in\n  full.\n\n## Out of scope\n\n- Fixing or creating `scripts/sync-books.sh`.\n- Re-vendoring the existing `full/` books against upstream's current\n  commit.\n- The panic-grep pre-filter and the subagent fan-out pattern, both\n  declined for this design.\n- Vendoring separate nano/mini files for the security corpus — it uses a\n  same-file partial read instead, since each YAML already separates\n  metadata/summary from examples.\n\n## Risks\n\n- The judgment gate (\"escalate to mini/full only when it matters\") has no\n  mechanical enforcement. This repo's own Gate 4b history shows an\n  unenforced step tends to erode under time pressure.\n- Vendoring surface triples from 14 files to 42, while the sync pipeline\n  that would check them against upstream (`scripts/sync-books.sh`) is\n  already missing.\n- The security corpus applicability read also has no mechanical\n  enforcement. Its default-to-full bias on ambiguity is meant to make a\n  false \"not applicable\" verdict less likely, not impossible.\n\n## How this was tested\n\nNo code changes; this design writes `docs/` artifacts only. Verification\nis: `book-index.md`'s escalation rule reads unambiguously, and the new cap\nlanguage explicitly supersedes the old 1+1 cap rather than leaving both\nstated at once.\n\n## Where to focus\n\n- Whether the judgment-gated escalation language in `book-index.md` is\n  specific enough to actually change agent behavior, or vague enough to be\n  silently ignored.\n- Whether the rewritten cap conflicts with any other reference file that\n  still assumes the old 1+1 cap.\n- Whether the security corpus's opposite default bias (full-on-ambiguity)\n  is stated clearly enough that a session doesn't quietly collapse it into\n  the same skip-on-ambiguity behavior as book escalation.\n\nThe author flagged these parts as not fully understood:\n- Whether upstream's nano/mini files exist for all 14 currently-vendored\n  books at a syncable commit — not verified in this design.\n\n---\n\nAuthorship: agent-generated.\n"}, "build-workflow-polish": {"goal": {"name": "build-workflow-polish", "title": "Fix four friction points found using the plugin family on a real project", "created": "2026-08-27", "outcome": "An engineer running architect:design into implement:start never loses the handoff, 04-slices.md is always written in the shape verify_gate.py actually parses, a validated slice is committed without an extra prompt, and the bundle viewer borrows the tab-based Diagram / Data flow / Data types layout a colleague prototyped.", "done_when": [], "abort_if": [], "min_work": {"derived_from": "Direct feedback from using cobuilder-plugin end to end on a separate real project on 2026-08-26/27. Four independent gaps surfaced, none touching the same file: architect:design's Stage 7 (references/design-mode.md) ends the mode without naming /implement:start as the next step; a session drafted 04-slices.md in a table shape slice_table.py's _ROW_RE_6COL/_ROW_RE_4COL do not match, so verify_gate.py and build_index.py silently failed to read it; build/SKILL.md's 'After each slice' step asks the user whether to commit instead of committing once VALIDATE clears the 0.90 threshold; and a colleague's diagram-viewer.html (scratchpad artifact, not in this repo) demonstrated a tabbed Diagram/Data-flow/Data-types layout with a collapsible left rail worth adopting for viewer/index.html.", "challenge_stage_run": false, "note": "Stage 0 and stage 1 grounding did not run. Stages 2 through 7 are deliberately deferred. This design is a backlog entry, not an approved design. It carries no intent.json, narrative.json, assessment.json, or diagrams, and it must not be implemented until design mode runs to completion for each epic that needs it."}, "limits": {"warn_after_rounds": 3, "cutoff_rounds": 6}, "epics": [{"id": "E1", "branch": null, "pr": null, "state": "completed", "note": "Stage 7 in architect's references/design-mode.md ends design mode after creating the first branch, with no pointer to what runs next. Add one line after the branch is created: 'Design mode's work ends here. To build this design's epics, run /implement:start.' Do not have design mode invoke implement:start itself — architecture modes are self-only in scope, and implement already owns Gate 1's design-record lookup (build/SKILL.md's 'Optional: design mode record' section). This is a one-line prose addition to a mode-governing reference file, so it still needs the Gate-selection exception's behavioral rubric, not a skip."}, {"id": "E2", "branch": null, "pr": null, "state": "completed", "note": "04-slices.md's Gate 4a instructions in build/SKILL.md describe the table only through the worked example, and never say the table must match shared/slice_table.py's exact column shape (six columns: #, Epic, Slice, Ends with, Score, State, with the epic-header row's precise empty-cell pattern) or point to that module as the source of truth. Add an explicit sentence and a link, so an authoring session does not freehand a table shape verify_gate.py silently fails to parse. Consider also having verify_gate.py surface parse_table()'s `unparsed` list by name when it is non-empty, instead of only reporting downstream symptoms like a missing epic."}, {"id": "E3", "branch": null, "pr": null, "state": "completed", "note": "build/SKILL.md's 'After each slice' section (the four numbered steps following the red-green-validate loop) records the score and asks 'Proceed to the next slice, or adjust direction?' but never commits. In practice this produces a spurious 'want to commit this checkpoint first?' prompt after every slice instead of an automatic commit. Change step 2 (or add a step) so that once VALIDATE scores a slice at or above 0.90, the orchestrator commits the slice's changes to git immediately, before asking whether to proceed — no confirmation question for the commit itself, only for what comes after. A score below threshold still routes through the existing gap decision tree in references/validation-scoring.md, and does not commit. Below-threshold slices accepted with reservations after three attempts should also commit, since that path already represents a final accepted state, not a pending one."}, {"id": "E4", "branch": null, "pr": null, "state": "planned", "note": "A colleague's scratch artifact (/private/tmp/.../diagram-viewer.html, session-local, not part of this repo) uses a top-of-panel tab switcher across three views — Diagram, Data flow, Data types — instead of stacking them, plus a right-hand info rail. Evaluate adopting the same top-tab pattern for viewer/index.html's per-PR diagram levels (currently level 1/2/3 switching, per ADR-0020's viewer/src/ plan), and separately evaluate narrowing the left-hand navigation rail so it takes less width once tabs handle top-level switching. This touches only the viewer, so it can run through architect:design on its own without waiting on E1-E3."}], "stage": "superseded", "supersedes": null, "adr": null, "adrs": [], "rounds": [], "superseded_by": "react-viewer", "superseded_note": "Superseded by react-viewer (ADR-0023) on 2026-09-07 at the engineer's direction. E4, the tab-based viewer layout, is absorbed by react-viewer's Work and Flight deck surfaces. E1, E2, and E3 are not viewer work, and react-viewer's E8 carries all three, so closing this design loses nothing."}}, "cobuilder-implement": {"goal": {"name": "cobuilder-implement", "title": "CoBuilder Implement — a design becomes verified code", "created": "2026-08-19", "outcome": "The architecture design produced by cobuilder-architect carries directly into implementation: its intent is decomposed into testable epics, and each epic ships as vertical slices that an independent validator scores at 0.90 or better before the next one starts.", "done_when": ["the skill runs G1 through G4 and stops at each gate for approval", "a slice is scored at 0.90 or better by a validator that executes the tests and never wrote the code", "an epic below 0.90 loops back to GREEN and closes", "cobuilder-implement builds one real change end to end under its own gates"], "abort_if": ["0.90 proves unreachable in practice, so most real slices escalate rather than pass, which makes the threshold theatre"], "min_work": {"derived_from": "6 districts (skills, scripts, commands, viewer, docs, .cobuilder-architect), 3 related ADRs, 1 boundary rule on install surface", "alternatives_explored": 5, "boundary_rules_checked": true, "challenge_stage_run": true}, "limits": {"warn_after_rounds": 3, "cutoff_rounds": 6}, "epics": [{"id": "E1", "branch": "design/design-mode", "pr": 11, "state": "open", "note": "Shares a branch and a pull request with the design-mode design. See ADR-0013: a branch may carry more than one design."}, {"id": "E2", "branch": "docs/post-pr11-cleanup", "pr": 12, "state": "open", "note": "Gate 4b is enforced instead of merely specified. The per-epic technical solution design already exists in SKILL.md section 4b, with a six-section template, and five downstream files reference the artifact. Nothing checks that it was written. Checked on 2026-08-24: zero epic-<id>-design.md files exist, and six epics shipped without one. Four failures allow that. Gate 4's only exit check counts rubrics, so a Gate 4 that skips 4b still passes. slice-loop.js builds the epic-design path and never checks the file exists, so the red and green agents are told to read a file that is absent and quietly fall back to 03-program-design.md. rubric-authoring.md tells the author to update the technical design first, and nobody checks that either. No test asserts the artifact. The root cause is that 4b is the only Gate 4 sub-step whose output nothing downstream mechanically requires: the loop cannot score without rubrics or iterate without a slice plan, but it can read an absent design. This epic adds the exit check, the existence guard in the workflow, a test, and sub-step tracking in 00-status.md so an approved Gate 4 cannot hide a missing 4b. Raised 2026-08-22, re-scoped 2026-08-24 from 'write the process' to 'enforce the process' after reading the skill."}], "stage": "approved", "supersedes": null, "adr": "ADR-0012", "adrs": ["ADR-0012", "ADR-0011", "ADR-0015"], "rounds": [{"n": 1, "changed": true, "feedback_class": "material"}]}, "intent": {"problem": "Software Factory gates the design, then accepts a slice on the implementer's own word. CoBuilder Guardian scores independently, but runs only on the pi SDK. Neither turns an approved design into verified code in an arbitrary harness, so the designs cobuilder-architect produces have nothing that consumes them.", "approach": "Three tiers and four gates. An initiative holds epics, a feature is an epic, and every epic must be testable. An epic holds vertical slices. Three separate agents build each slice: one writes failing tests, one writes the minimal code and never edits a test, and one validates. The validator executes the suite, then reads the code and judges whether the tests cover the declared outcomes. A slice needs 0.90 or better. The epic gate is hard, and remediation returns to the implementing agent until it closes.", "alternatives": [{"option": "One agent does the rubric, the tests, the code, and the self-report in a single context, and a human skims the log at the end", "rejected_because": "It abandons independent scoring, which the outcome requires. The agent that wrote the code judges its own test run, which is the most gameable pattern available."}, {"option": "Delete the validator. Get blindness from context amnesia: one agent writes the rubric, the harness clears context, and the same agent implements and self-scores twice, voiding on a mismatch above 0.15", "rejected_because": "Erasure blindness cannot be verified from outside the model, and two runs of one policy give correlated error rather than independent verification. It assumes away the hard part."}, {"option": "Treat rubrics as a cross-repo append-only ledger, cluster criterion fingerprints into a shared genome, and prime the validator with a prior score distribution", "rejected_because": "It needs a periodic clustering job across repos, which breaks the rule that this skill uses no external service and no pipeline runtime. It also solves a volume problem this work does not have yet."}, {"option": "Forbid the validator from reading the implementation at all, and score only from a test runner's exit codes", "rejected_because": "It scores whether tests pass and never asks whether the tests are worth passing. The validator must also judge test adequacy against the specs, so it reads the code after it executes the suite."}, {"option": "Commit a hash of every test file at G3 and check it before scoring", "rejected_because": "It changes the G3 gate contract for a hole that a validator judging test adequacy already covers. The void triggers widen in prose instead."}, {"option": "Score a criterion called 'no undeclared test dependencies' to catch a fixture added after G3", "rejected_because": "Enumerating a test's transitive dependencies is not free in a dynamically imported language. The same reasoning as the hash check applies."}, {"option": "Strip the validator's retry feedback to pass or fail per criterion, so accumulated feedback cannot leak the rubric's shape", "rejected_because": "Rich feedback is mandatory for GREEN to improve within its attempts. Starving it pushes slices into escalation, which costs more than the leak."}], "authorship": "bjoerns, with Claude drafting and challenging", "captured": "2026-08-19", "design": {"name": "cobuilder-implement", "epic": null}, "design_name": "cobuilder-implement", "out_of_scope": ["opening a pull request or pushing a branch — that stays submit mode's job in cobuilder-architect", "changing design mode, which this design consumes and does not modify", "any code dependency between the two plugins in either direction", "agents, hooks, and MCP servers, so the plugin never touches another session's permission surface", "running the skill on a real initiative, which follows the build"], "reviewer_focus": ["the validator's mandate — it executes the suite, then reads the code and judges whether the tests cover the declared outcomes", "the epic gate and its remediation loop, which has no automatic escalation and relies on a human check-in every three remediations", "the light path, which removes the panels for a single-epic initiative but never the slice loop or the 0.90 gate", "the join contract path, which is written in two plans and breaks silently if one moves"], "risks": ["blindness is honour-based: nothing mechanically stops an implementer reading the rubric directory, and detection depends on the validator noticing", "at volume, a validator pool statistically absorbs the shape of passing rubrics, so prompt discipline leaks and no filesystem permission was ever there to catch it", "just-in-time detailing can redefine a cross-epic contract another epic depends on; the frozen-contract rule is a rule, not a mechanism", "the ledger records what agents claim, so a rigged run writes a clean-looking entry; it buys auditability, not integrity", "a validator that must judge test adequacy does more work per slice, which raises cost and slows every gate"], "source": "authored", "testing": "The skill is prose plus two workflow scripts, so verification is static plus one end-to-end run. Parse both scripts wrapped in an async function, because the runtime wraps them and a bare top-level return fails a plain module check. Confirm every reference named in SKILL.md exists and is reachable. Grep for retired names. Then run the skill against a throwaway feature and confirm it reaches the G3 rubric gate check and stops for approval. The stop condition is self-hosting: it builds one real change end to end under its own gates.", "unknowns": ["whether 0.90 is reachable often enough in practice that escalation stays the exception", "whether a validator judging test adequacy scores consistently enough run to run for the number to mean anything", "whether the manual three-role mode degrades acceptably in a harness with no scripted runner", "how many remediation rounds a real epic needs before the human check-in fires"], "why_now": "Design mode shipped, so designs now carry intent that nobody has to reconstruct. The half that turns a design into code does not exist, so the intent stops at the branch name."}, "assessment": {"verdict": "proceed", "findings": [{"kind": "prediction", "id": "F1", "severity": "medium", "title": "Blindness has no mechanical enforcement", "detail": "Rubrics live in .cobuilder/rubrics/ inside the repo, so nothing stops an implementing agent reading them. Enforcement is prompt discipline plus a void rule applied after the fact, and detection depends on the validator noticing. The engineer accepted this risk deliberately, choosing in-repo storage over a second repository.", "cites": "ADR-0012", "mitigation": "Three layers rather than one: the prompt forbids the read, the implementer never receives the rubric path, and a detected read voids the score at no attempt cost instead of lowering it."}, {"kind": "prediction", "id": "F2", "severity": "high", "title": "The join contract path is written in two plans and can break silently", "detail": "docs/architecture/designs/<name>/intent.json is the only coupling between cobuilder-architect and cobuilder-implement. It appears in this design and in the design-mode plan. A move in one without the other leaves the reader plugin looking at an absent file, and the failure mode is a silent fallback to drafting a Business Spec from scratch rather than an error.", "cites": "ADR-0013", "mitigation": "Record the coupling as a constraint introduced in the ADR, so a future session changing either plan is told the other moves with it. A missing file must report that it looked and found nothing, never fall through silently."}, {"kind": "prediction", "id": "F3", "severity": "medium", "title": "Cross-epic contracts freeze by rule, not by mechanism", "detail": "Just-in-time Technical Specs only work when epics are separable. A skeleton names the contracts an epic exposes or consumes, and those freeze at G1. Nothing checks that a later detailing pass honoured them, and nothing checks that the skeleton named them honestly in the first place.", "cites": "district: docs", "mitigation": "A change to a frozen contract is a backtrack to G1 with re-approval. The rule is stated, and the risk of an unhonest skeleton stays open."}, {"kind": "prediction", "id": "F4", "severity": "medium", "title": "The validator now carries two jobs, and the second is subjective", "detail": "The validator executes the suite, then reads the code and judges whether the tests are sensible and cover the declared outcomes. Execution is objective. Test adequacy is judgment, and judgment scored on a three-value scale may not repeat run to run. If the second job scores inconsistently, the 0.90 number stops meaning one thing.", "cites": "ADR-0012", "mitigation": "Every criterion cites evidence — a test name, captured output, or a file and line. A score without evidence does not count. Consistency is listed as an unknown to be measured on real slices, not assumed."}, {"kind": "prediction", "id": "F5", "severity": "low", "title": "The ledger records claims, not facts", "detail": "An append-only record of each scored slice, with the validator's stated reason per criterion, makes a stalled initiative resumable and makes a score explicable. It does not make a score true. A rigged run writes a plausible entry.", "cites": "district: docs", "mitigation": "State the limit where the ledger is defined. It buys auditability, and it is not a fix for validation integrity."}, {"kind": "prediction", "id": "F6", "severity": "low", "title": "Ceremony may exceed the work on small initiatives", "detail": "A multi-epic initiative runs one refute panel, plus a research panel and a skeptic per epic, before the first slice starts. On a two-day feature that is heavier than the feature.", "cites": "ADR-0012", "mitigation": "The light path collapses a single-epic initiative to one spec and removes the panels, the skeptic, and the epic rubric. The slice loop and the 0.90 gate never switch off."}], "boundary_checks": ["no agents, no hooks, and no MCP servers, so the plugin never touches another session's permission surface", "no code dependency on cobuilder-architect in either direction; the join is one file", "no external service and no pipeline runtime; the manual three-role mode is the portable fallback"], "drift": [], "regret_risk": "low", "risk_tier": "medium", "stage": "design", "summary": "The design is internally consistent and its constraints are honest. Every finding below is a prediction, because no code exists yet. The two that matter are the honour-based blindness the engineer accepted knowingly, and the cross-plan contract path that breaks silently if one plan moves without the other."}, "narrative": {"landscape": {"tagline": "A design becomes verified code, one slice at a time.", "narration": "cobuilder-architect can now capture a design before any code exists, but nothing on the other side of that record turns it into working software under independent checks. This design adds the missing half: four approval gates before implementation starts, and a validator that never wrote the code deciding whether each slice is actually done."}, "problem_solution": {"problem": "Software Factory gates a design, then accepts a finished slice on the implementer's own word. CoBuilder Guardian scores independently, but it only runs on the pi SDK, DOT pipelines, beads, and Hindsight. Neither one takes an approved architecture design and turns it into verified code in an arbitrary coding harness, so the designs `cobuilder-architect` now produces have nothing that consumes them.", "solution": "Three tiers and four gates. An initiative holds epics, a feature is an epic, and every epic must be testable. An epic holds vertical slices. Three separate agents build each slice: one writes failing tests, one writes the minimal code and never edits a test, and one validates. The validator executes the suite, then reads the code and judges whether the tests cover the declared outcomes. A slice needs a score of `0.90` or better. The epic gate is hard, and remediation returns to the implementing agent until it closes.", "narration": "Design mode already writes down what a change is for and why, before the change exists. This design gives that record somewhere to go. It borrows the gate discipline of Software Factory, which settles every hard decision in prose while it is still cheap to change, and it borrows the independent scoring of CoBuilder Guardian, which never lets the agent that wrote the code grade its own test run. Joining the two means a design can walk all the way to working software, with a validator checking every step who was never shown the code while writing the checklist.", "beats": [{"kind": "background", "text": "`cobuilder-architect`'s design mode shipped first, so a design now carries intent, alternatives, and constraints that nobody has to reconstruct later (ADR-0011). ADR-0015 then made the architecture modes self-only, which means a build workflow cannot live inside `cobuilder-architect` itself. The design that mode produces has nothing downstream that reads it and turns it into code."}, {"kind": "background", "text": "Software Factory's weakness sits at the end of a slice: the agent that built the slice proves it works by running it and showing the result, so the same agent decides what counts as proof. CoBuilder Guardian answers that weakness by writing acceptance rubrics before implementation starts, storing them where the implementer cannot read them, and scoring the result with an agent that did not write the code. Its weakness is the runtime: it needs the pi SDK, DOT pipelines, beads, and Hindsight, none of which runs in another harness."}, {"kind": "intuition", "text": "Take a single epic with three slices. Slice one gets a rubric written before any code exists, hidden from the implementer. The GREEN agent writes the minimal code, the validator runs the test suite it never touched, reads the resulting code, and scores it against the rubric. A score of `0.85` sends the slice back to GREEN with the validator's stated reasons; a score of `0.90` or better closes it and starts the next slice. Nothing in that loop lets the agent that wrote the code also decide it is finished."}], "alternatives": [{"option": "One agent does the rubric, the tests, the code, and the self-report in a single context, and a human skims the log at the end", "rejected": "It abandons independent scoring, which the outcome requires. The agent that wrote the code judges its own test run, which is the most gameable pattern available."}, {"option": "Delete the validator. Get blindness from context amnesia: one agent writes the rubric, the harness clears context, and the same agent implements and self-scores twice, voiding on a mismatch above 0.15", "rejected": "Erasure blindness cannot be verified from outside the model, and two runs of one policy give correlated error rather than independent verification. It assumes away the hard part."}, {"option": "Treat rubrics as a cross-repo append-only ledger, cluster criterion fingerprints into a shared genome, and prime the validator with a prior score distribution", "rejected": "It needs a periodic clustering job across repos, which breaks the rule that this skill uses no external service and no pipeline runtime. It also solves a volume problem this work does not have yet."}, {"option": "Forbid the validator from reading the implementation at all, and score only from a test runner's exit codes", "rejected": "It scores whether tests pass and never asks whether the tests are worth passing. The validator must also judge test adequacy against the specs, so it reads the code after it executes the suite."}, {"option": "Commit a hash of every test file at G3 and check it before scoring", "rejected": "It changes the G3 gate contract for a hole that a validator judging test adequacy already covers. The void triggers widen in prose instead."}, {"option": "Score a criterion called 'no undeclared test dependencies' to catch a fixture added after G3", "rejected": "Enumerating a test's transitive dependencies is not free in a dynamically imported language. The same reasoning as the hash check applies."}, {"option": "Strip the validator's retry feedback to pass or fail per criterion, so accumulated feedback cannot leak the rubric's shape", "rejected": "Rich feedback is mandatory for GREEN to improve within its attempts. Starving it pushes slices into escalation, which costs more than the leak."}]}, "architecture": {"narration": "No plugin here takes a code dependency on another. `cobuilder-implement` joins `cobuilder-architect` through one file, `docs/architecture/designs/<name>/intent.json`, and joins nothing else. The install surface stays fixed: no agents, no hooks, no MCP servers, so the plugin never touches another session's permission surface. Everything else — the gates, the rubric store, the validator's mandate — is prose plus two workflow scripts that any harness able to spawn a subagent can run.", "beats": [{"kind": "forces", "text": "The skill must run in any harness that can spawn a subagent, with no SDK, no pipeline runtime, and no external service. An implementing agent that reads the rubric writes to the rubric, not to the requirement. An agent that wrote code cannot score it, because it reads its own intent into the code. ADR-0015 makes the architecture modes self-only, so a build workflow cannot live inside `cobuilder-architect`."}, {"kind": "contract", "text": "`docs/architecture/designs/<name>/intent.json` is the only coupling between the two plugins, in either direction. `cobuilder-implement` reads it as the hypothesis for the initiative it builds. No shared code, no shared runtime, and no arrow from either plugin to the other's files."}, {"kind": "boundary", "text": "Blindness is honour-based inside one repository: rubrics live in `.cobuilder/rubrics/`, and nothing mechanically stops an implementing agent from reading them. Enforcement is three layers — the prompt forbids the read, the implementer never receives the rubric path, and a detected read voids the score at no attempt cost rather than lowering it. Opening a pull request or pushing a branch stays submit mode's job in `cobuilder-architect`, never this plugin's."}]}}, "diagrams": {"1": "C4Container\n    title \"cobuilder-implement design: two plugins joined by one file, no code dependency\"\n\n    Person(engineer, \"Engineer\", \"Approves gates, runs both plugins in the same coding harness\")\n\n    Container_Boundary(target, \"Target repo\") {\n        Container(intentfile, \"intent.json\", \"JSON file\", \"docs/architecture/designs/<name>/intent.json — the only join between the two plugins\")\n    }\n\n    Container_Boundary(architect, \"cobuilder-architect plugin — designs\") {\n        Container(designmode, \"design mode\", \"skill\", \"Interviews the engineer, writes intent.json and the ADR before code exists\")\n    }\n\n    Container_Boundary(implement, \"cobuilder-implement plugin — builds\") {\n        Container(gates, \"G1-G4 gates\", \"skill\", \"Business Spec, Technical Spec, Slice Plan and Rubrics, Acceptance\")\n        Container(validator, \"VALIDATE subagent\", \"subagent\", \"Executes tests, then reads code, scores against a blind rubric\")\n    }\n\n    Rel(engineer, designmode, \"Runs design mode on\")\n    Rel(designmode, intentfile, \"Writes\")\n    Rel(engineer, gates, \"Runs G1 to start build on\")\n    Rel(gates, intentfile, \"Reads at G1 to ground the Business Spec\")\n    Rel(gates, validator, \"Spawns per slice\")\n\n    UpdateRelStyle(designmode, intentfile, $offsetX=\"10\", $offsetY=\"-10\")\n    UpdateRelStyle(gates, intentfile, $offsetX=\"-10\", $offsetY=\"10\")\n", "2": "sequenceDiagram\n    participant Orchestrator\n    participant RED as RED subagent\n    participant GREEN as GREEN subagent\n    participant VALIDATE as VALIDATE subagent\n    participant Suite as Test suite (fresh process)\n    participant Ledger as Per-epic ledger\n\n    Orchestrator->>RED: Spawn for this slice\n    RED->>RED: Write failing tests against the blind rubric's declared outcomes\n    RED-->>Orchestrator: Failing tests committed\n\n    Orchestrator->>GREEN: Spawn with failing tests\n    GREEN->>GREEN: Write minimal code, never edit a test\n    GREEN-->>Orchestrator: Implementation ready\n\n    Orchestrator->>VALIDATE: Spawn to score the slice\n    VALIDATE->>Suite: Execute the suite in a fresh process\n    Suite-->>VALIDATE: Pass/fail results, no claimed result accepted\n    VALIDATE->>VALIDATE: Read the code and the tests, judge adequacy against specs\n\n    alt Score >= 0.90, no critical criterion below 1.0\n        VALIDATE->>Ledger: Append per-criterion score and stated reason\n        VALIDATE-->>Orchestrator: Slice accepted\n    else Score below 0.90\n        VALIDATE->>Ledger: Append per-criterion score and stated reason\n        VALIDATE-->>Orchestrator: Return to GREEN with full feedback\n        Orchestrator->>GREEN: Retry (up to 3 attempts total)\n        Note over Orchestrator,GREEN: After 3 attempts, escalate to a human check-in\n    else Rigged pass detected (edited/skipped/weakened test, swapped dependency, rubric read)\n        VALIDATE->>Ledger: Append VOID and stated reason\n        VALIDATE-->>Orchestrator: Void, no attempt cost\n        Orchestrator->>RED: Return to RED to rewrite the tests\n    end\n", "3": "classDiagram\n    class Initiative {\n        +businessSpec BusinessSpec\n        +epics Epic[]\n    }\n\n    class BusinessSpec {\n        <<visible>>\n        +problem string\n        +epicList string[]\n    }\n\n    class Epic {\n        +name string\n        +mustBeTestable bool\n        +technicalSpec TechnicalSpec\n        +epicRubric Rubric\n        +slices Slice[]\n    }\n\n    class TechnicalSpec {\n        <<visible>>\n        +writtenJustInTime bool\n        +researchVerified bool\n    }\n\n    class Slice {\n        +blindRubric Rubric\n        +score float\n        +attempts int\n        +maxAttempts int\n    }\n\n    class Rubric {\n        <<blind, implementer never reads it>>\n        +criteria Criterion[]\n    }\n\n    class Criterion {\n        +score float\n        +evidence string\n        +critical bool\n    }\n\n    class LedgerEntry {\n        <<append-only>>\n        +epic string\n        +slice string\n        +perCriterionScore float\n        +validatorReason string\n    }\n\n    class G1_BusinessSpec {\n        <<gate, once>>\n        +producesEpics() void\n    }\n\n    class G2_TechnicalSpec {\n        <<gate, per epic>>\n        +producesTechnicalSpec() void\n    }\n\n    class G3_SlicePlanAndRubrics {\n        <<gate, per epic>>\n        +producesSliceList() void\n        +producesBlindRubrics() void\n    }\n\n    class G4_Acceptance {\n        <<gate, per slice then per epic>>\n        +threshold float\n    }\n\n    Initiative \"1\" --> \"*\" Epic : decomposes into\n    Epic \"1\" --> \"1\" TechnicalSpec : holds\n    Epic \"1\" --> \"1\" Rubric : holds epic rubric\n    Epic \"1\" --> \"*\" Slice : holds\n    Slice \"1\" --> \"1\" Rubric : holds blind rubric\n    Rubric \"1\" --> \"*\" Criterion : contains\n    Slice \"1\" --> \"*\" LedgerEntry : scored into\n\n    G1_BusinessSpec ..> Initiative : attaches to\n    G1_BusinessSpec ..> Epic : attaches to\n    G2_TechnicalSpec ..> TechnicalSpec : attaches to\n    G3_SlicePlanAndRubrics ..> Slice : attaches to\n    G3_SlicePlanAndRubrics ..> Rubric : attaches to\n    G4_Acceptance ..> Slice : attaches to\n    G4_Acceptance ..> Epic : attaches to\n\n    note for Rubric \"BLIND: the implementer never reads Rubric or Criterion.\\nBusinessSpec and TechnicalSpec stay visible.\"\n"}, "pr_draft": "# CoBuilder Implement — a design becomes verified code\n\n## Problem\n\nSoftware Factory gates the design, then accepts a slice on the implementer's own word. CoBuilder Guardian scores independently, but runs only on the pi SDK. Neither turns an approved design into verified code in an arbitrary harness, so the designs cobuilder-architect produces have nothing that consumes them.\n\nDesign mode shipped, so designs now carry intent that nobody has to reconstruct. The half that turns a design into code does not exist, so the intent stops at the branch name.\n\n## Why this approach\n\nThree tiers and four gates. An initiative holds epics, a feature is an epic, and every epic must be testable. An epic holds vertical slices. Three separate agents build each slice: one writes failing tests, one writes the minimal code and never edits a test, and one validates. The validator executes the suite, then reads the code and judges whether the tests cover the declared outcomes. A slice needs 0.90 or better. The epic gate is hard, and remediation returns to the implementing agent until it closes.\n\n## Alternatives considered\n\n- **One agent does the rubric, the tests, the code, and the self-report in a single context, and a human skims the log at the end** — rejected because it abandons independent scoring, which the outcome requires. The agent that wrote the code judges its own test run, which is the most gameable pattern available.\n- **Delete the validator. Get blindness from context amnesia: one agent writes the rubric, the harness clears context, and the same agent implements and self-scores twice, voiding on a mismatch above 0.15** — rejected because erasure blindness cannot be verified from outside the model, and two runs of one policy give correlated error rather than independent verification. It assumes away the hard part.\n- **Treat rubrics as a cross-repo append-only ledger, cluster criterion fingerprints into a shared genome, and prime the validator with a prior score distribution** — rejected because it needs a periodic clustering job across repos, which breaks the rule that this skill uses no external service and no pipeline runtime. It also solves a volume problem this work does not have yet.\n- **Forbid the validator from reading the implementation at all, and score only from a test runner's exit codes** — rejected because it scores whether tests pass and never asks whether the tests are worth passing. The validator must also judge test adequacy against the specs, so it reads the code after it executes the suite.\n- **Commit a hash of every test file at G3 and check it before scoring** — rejected because it changes the G3 gate contract for a hole that a validator judging test adequacy already covers. The void triggers widen in prose instead.\n- **Score a criterion called 'no undeclared test dependencies' to catch a fixture added after G3** — rejected because enumerating a test's transitive dependencies is not free in a dynamically imported language. The same reasoning as the hash check applies.\n- **Strip the validator's retry feedback to pass or fail per criterion, so accumulated feedback cannot leak the rubric's shape** — rejected because rich feedback is mandatory for GREEN to improve within its attempts. Starving it pushes slices into escalation, which costs more than the leak.\n\n## Out of scope\n\n- opening a pull request or pushing a branch — that stays submit mode's job in cobuilder-architect\n- changing design mode, which this design consumes and does not modify\n- any code dependency between the two plugins in either direction\n- agents, hooks, and MCP servers, so the plugin never touches another session's permission surface\n- running the skill on a real initiative, which follows the build\n\n## Risks\n\n- blindness is honour-based: nothing mechanically stops an implementer reading the rubric directory, and detection depends on the validator noticing\n- at volume, a validator pool statistically absorbs the shape of passing rubrics, so prompt discipline leaks and no filesystem permission was ever there to catch it\n- just-in-time detailing can redefine a cross-epic contract another epic depends on; the frozen-contract rule is a rule, not a mechanism\n- the ledger records what agents claim, so a rigged run writes a clean-looking entry; it buys auditability, not integrity\n- a validator that must judge test adequacy does more work per slice, which raises cost and slows every gate\n\n## How this was tested\n\nThe skill is prose plus two workflow scripts, so verification is static plus one end-to-end run. Parse both scripts wrapped in an async function, because the runtime wraps them and a bare top-level return fails a plain module check. Confirm every reference named in SKILL.md exists and is reachable. Grep for retired names. Then run the skill against a throwaway feature and confirm it reaches the G3 rubric gate check and stops for approval. The stop condition is self-hosting: it builds one real change end to end under its own gates.\n\n## Where to focus\n\n- the validator's mandate — it executes the suite, then reads the code and judges whether the tests cover the declared outcomes\n- the epic gate and its remediation loop, which has no automatic escalation and relies on a human check-in every three remediations\n- the light path, which removes the panels for a single-epic initiative but never the slice loop or the 0.90 gate\n- the join contract path, which is written in two plans and breaks silently if one moves\n\nThe author flagged these parts as not fully understood:\n\n- whether 0.90 is reachable often enough in practice that escalation stays the exception\n- whether a validator judging test adequacy scores consistently enough run to run for the number to mean anything\n- whether the manual three-role mode degrades acceptably in a harness with no scripted runner\n- how many remediation rounds a real epic needs before the human check-in fires\n"}, "design-mode": {"goal": {"name": "design-mode", "title": "Design mode for cobuilder-architect", "created": "2026-08-19", "outcome": "An engineer can design a change with the plugin before writing it, and the resulting intent, ADR, and diagrams carry through to the pull request that implements it.", "done_when": ["/cobuilder-architect:design runs the seven stages and writes a design directory", "submit mode resolves a design from the branch name and skips the cold interview", "the viewer lists and renders designs alongside the PR timeline"], "abort_if": ["the challenge stage cannot be made to produce rejected options reliably, leaving every ADR with a single considered option", "the architecture skill cannot be merged, leaving design mode without a corpus to reason with"], "min_work": {"derived_from": "3 districts (skills, scripts, viewer), 2 colliding ADRs, 1 boundary rule on install surface", "alternatives_explored": 3, "boundary_rules_checked": true, "challenge_stage_run": true}, "limits": {"warn_after_rounds": 3, "cutoff_rounds": 6}, "epics": [{"id": "E1", "branch": "design/design-mode", "pr": 11, "state": "open", "note": "Design mode as a pre-code interview and challenge gate. Shares a branch and a pull request with the cobuilder-implement design. See ADR-0013: a branch may carry more than one design."}], "stage": "implemented", "supersedes": null, "adr": "ADR-0011", "adrs": ["ADR-0011", "ADR-0014", "ADR-0015"], "rounds": [{"n": 1, "changed": true, "feedback_class": "material"}, {"n": 2, "changed": true, "feedback_class": "material"}, {"n": 3, "changed": true, "feedback_class": "cosmetic"}]}, "intent": {"problem": "The plugin captures author intent at submit time, after the change exists. Nothing captures it at design time, when the engineer still holds the alternatives, the constraints, and the doubts. Generate mode then reconstructs intent from merged code, which is the guessing the plugin was built to stop.", "approach": "A seventh mode, /prodyssey:design, running seven stages: name and outcome, ground, interview, explore, challenge, draft, review, branch. It writes a named design directory under exports/, never the timeline, and ends by creating a branch that submit mode later resolves by name.", "alternatives": [{"option": "Put design mode in archkit instead, next to its existing design mode", "rejected_because": "The interview discipline, the bundle, the diagram pipeline, and the viewer all live in prodyssey. archkit's contribution is a skill call. Building it in archkit would mean porting four subsystems to reach one."}, {"option": "Keep archkit a soft, optional dependency and degrade when it is absent", "rejected_because": "A design mode whose substance is optional degrades silently into a chat. The corpus and the divergent exploration are the design content, not an enhancement to it."}, {"option": "Ask the engineer which options they rejected, as an interview question", "rejected_because": "Nobody can name a rejected option before the design exists. A rejected option is an outcome of the design process, not an input to it. Stages 3 and 4 produce them instead."}, {"option": "Mint a synthetic PR key so a design can enter the story.json timeline directly", "rejected_because": "story.json keys on an integer pr, and verify_bundle.py, record_publish.py, manifest.js, and the viewer all depend on it. Submit mode already stages outside the timeline for this reason."}, {"option": "Review designs in a Lavish surface rather than the bundle viewer", "rejected_because": "Element-level annotation is a better review loop, but it adds an external dependency to a plugin that deliberately has none. The viewer already renders assessments and is committed with the repo."}], "authorship": "agent-assisted", "captured": "2026-08-19", "design_name": "design-mode", "out_of_scope": ["opening a pull request — that stays submit mode's job", "pushing a branch or any other remote action", "element-level annotation or a send-to-agent channel in the viewer", "renaming the repository", "deciding the fate of the archkit repository"], "reviewer_focus": ["stage 4, the challenge gate — it is the sole producer of rejected options", "section 3, the branch-name lookup that joins a design to its pull request", "the CLAUDE.md passages that the merge deliberately breaks"], "risks": ["the agreeable design: exploration finds nothing contradicting the engineer, and the ADR records one choice instead of a decision", "a design-stage prediction read as a verified observation, because it cites an ADR id rather than a path:line", "the design and its branch diverge silently after stage 7", "the duplicate-design subagent reports no match and the engineer trusts it"], "source": "design", "testing": "Not yet built. This design directory is itself the first test of the layout: it was authored by hand against the proposed shape.", "unknowns": ["whether a semantic duplicate-design search is accurate enough that an engineer can trust a no-match answer", "how much the 3.1 MB architecture skill slows a plugin install in practice", "whether material and cosmetic review feedback can be classified reliably enough to route automatically"], "why_now": "Submit mode's intent block already has the right shape for a design. The bundle already holds districts, ADRs, and a timeline to design against. The archkit architecture skill already holds the corpus and the divergent exploration that a design needs. The three parts exist and are not connected."}, "assessment": {"verdict": "proceed", "findings": [{"kind": "observation", "id": "F1", "severity": "low", "title": "Design mode shipped and moved, as goal.json's outcome describes", "detail": "plugins/cobuilder-architect/commands/design.md exists and dispatches to the architecture skill. No skills/odyssey directory or root-level commands/ directory exists anywhere in the tree today. The mode is not present under plugins/cobuilder-pr, which now ships five modes (baseline, review, generate, view, publish) with no design mode among them. This matches CLAUDE.md's Recent history entry: design mode moved from the odyssey skill into the architecture skill, leaving odyssey with five modes.", "cites": "plugins/cobuilder-architect/commands/design.md; absence of skills/odyssey and commands/ at the repository root", "mitigation": "None needed. This is the shipped, intended state."}, {"kind": "observation", "id": "F2", "severity": "low", "title": "commands/explore-design.md is confirmed deleted", "detail": "No file named explore-design.md exists anywhere in the current tree. git log on docs/architecture/designs/design-mode/adr-draft.md and the surrounding commit history are consistent with CLAUDE.md's Recent history note that explore-design.md was deleted as a duplicate of design.md.", "cites": "find . -iname 'explore-design*' returns no results", "mitigation": "None needed."}, {"kind": "drift", "id": "F3", "severity": "medium", "title": "ADR-0011's maps_to.modules names two paths that predate the five-plugin split", "detail": "ADR-0011's frontmatter lists maps_to.modules as skills/odyssey and commands. Neither path exists today. The command that implements this decision lives at plugins/cobuilder-architect/commands/design.md, and the skill it dispatches to is plugins/cobuilder-architect/skills/architecture/. The ADR was decided on 2026-08-19, before ADR-0016 and ADR-0017 split the single plugin into five and moved every root-level skills/ and commands/ directory into per-plugin roots. Nothing updated the ADR's maps_to block afterward.", "cites": "docs/architecture/adr/ADR-0011-design-mode.md, maps_to.modules; plugins/cobuilder-architect/commands/design.md", "mitigation": "Update ADR-0011's maps_to.modules to plugins/cobuilder-architect/commands and plugins/cobuilder-architect/skills/architecture, or mark the field historical and add a current-location note."}, {"kind": "drift", "id": "F4", "severity": "low", "title": "intent.json's approach paragraph names a dropped plugin name and a rejected output location", "detail": "intent.json's approach field reads: \"A seventh mode, /prodyssey:design ... It writes a named design directory under exports/, never the timeline.\" The plugin was renamed from prodyssey to cobuilder-architect, and the shipped command is /cobuilder-architect:design. The shipped output location is docs/architecture/designs/<name>/, per goal.json's done_when and ADR-0011's decision text, not exports/. This sentence was captured on 2026-08-19, the same day as the ADR, and reads as an early draft overtaken by the decision recorded in the same design.", "cites": "docs/architecture/designs/design-mode/intent.json, approach field; docs/architecture/designs/design-mode/goal.json, done_when[0]", "mitigation": "Either update the approach sentence to match the shipped command and path, or add a note that intent.json is a point-in-time capture and the ADR supersedes it on naming and location."}, {"kind": "observation", "id": "F5", "severity": "low", "title": "The design's pr-draft.md is now projected into the record index", "detail": "shared/build_index.py reads pr_draft_path = path.parent / 'pr-draft.md' at line 431, inside the function that walks each design directory. This design directory has no pr-draft.md of its own to project, but the code path that was missing is present in the script this branch ships.", "cites": "shared/build_index.py:431", "mitigation": "None needed for this design. Worth reconfirming the same line exists in each plugin's vendored shared/build_index.py copy before this fix is treated as universal."}, {"kind": "observation", "id": "F6", "severity": "low", "title": "adr-draft.md is gone, consistent with promotion to ADR-0011", "detail": "docs/architecture/designs/design-mode/ holds no adr-draft.md today. The file was deleted on 2026-08-25, as part of the change on this branch that retires adr-draft.md as a documented artifact type, with the matching line removed from CLAUDE.md and README.md in the same change. The draft was ADR-0011, already promoted to docs/architecture/adr/ADR-0011-design-mode.md. It was stale on the same two counts F4 records for intent.json: it named /prodyssey:design and it named exports/ as the output location. git status --short confirms the deletion is uncommitted at the time of writing.", "cites": "git log --oneline -- docs/architecture/designs/design-mode/adr-draft.md", "mitigation": "None needed. Flagging only the unverified deletion commit for completeness."}, {"kind": "observation", "id": "F7", "severity": "medium", "title": "Epic E1's pull request is open, and the index cannot resolve that state", "detail": "goal.json.epics[0] declares pr: 11 and state: 'open'. gh pr view 11 confirms pull request 11 is OPEN on GitHub today, so the declared state matches reality. But shared/build_index.py's collect_pull_requests() (line 641) reads only entries already present in data/story.json's timeline, which holds narrated, merged pull requests. refine_epic_status() (line 791) looks up each epic's pull request number in that same narrowed set and only overwrites the placeholder status when a match exists. Pull request 11 has not been narrated, so no match exists, and the index cannot derive its open state from the bundle alone. The goal.json field is the only place that state is recorded correctly right now.", "cites": "shared/build_index.py:641-665 (collect_pull_requests), shared/build_index.py:791-797 (refine_epic_status); goal.json epics[0]; gh pr view 11", "mitigation": "Either narrate pull request 11 once it is available to review mode, so the index can pick up its real state, or extend refine_epic_status to fall back to a live gh pr view lookup for epics whose pull request never entered the timeline."}], "boundary_checks": [{"rule": "No agents, no hooks, no MCP servers in the install surface", "result": "holds", "note": "Design mode is a skill dispatch from a command file, the same shape as every other architecture mode."}, {"rule": "Architecture modes are self-only and take no --repo", "result": "holds", "note": "plugins/cobuilder-architect/commands/design.md carries no --repo handling, consistent with the other five architecture commands."}, {"rule": "A design lives under docs/architecture/designs/<name>/ and never enters story.json until a real PR number exists", "result": "holds", "note": "This design's own directory is exactly that shape, and its pull request, 11, is a real number returned by gh pr create, not a synthetic key."}], "drift": [{"kind": "drift", "title": "ADR-0011's maps_to.modules names pre-split paths", "detail": "See F3. skills/odyssey and commands no longer exist as top-level paths after the five-plugin split (ADR-0016, ADR-0017). The ADR's own maps_to block was never updated to name plugins/cobuilder-architect/commands and plugins/cobuilder-architect/skills/architecture."}, {"kind": "drift", "title": "intent.json still names the pre-rename plugin and a rejected output root", "detail": "See F4. The approach field says /prodyssey:design writing under exports/. The shipped command is /cobuilder-architect:design, writing under docs/architecture/designs/<name>/."}, {"kind": "drift", "title": "Epic E1's real-world pull request state is invisible to the generated index", "detail": "See F7. Pull request 11 is open on GitHub and correctly recorded as such in goal.json, but shared/build_index.py can only refine an epic's status from pull requests already narrated into data/story.json's timeline. An open, un-narrated pull request leaves the index with only its initial placeholder, not the live GitHub state."}], "regret_risk": "low", "risk_tier": "medium", "stage": "retrospective", "summary": "This assessment was written on 2026-08-25, after design mode shipped, because the file was found missing from the design directory. It is a retrospective, not a design-stage prediction. Every finding below states what a check against the tree today found, not what an author foresaw before the code existed. Design mode shipped, moved from the odyssey skill into the architecture skill, and its command now lives at plugins/cobuilder-architect/commands/design.md. The design's own record carries two stale paths from before the five-plugin split, and its lone epic sits in a state the index cannot yet resolve because its pull request is open, not merged."}, "narrative": {"landscape": {"narration": "This design adds a seventh Odyssey mode so an engineer can record intent, alternatives, and constraints before any code exists, then carry that record through to the pull requests that implement it.", "tagline": "Design before the change exists."}, "problem_solution": {"narration": "Submit mode already captures intent, but only after the change exists. The alternatives are already closed. Design mode reaches the earlier moment, writes a named design under docs/, and joins N pull requests through an epics array.", "problem": "The plugin captures author intent at submit time, after the change exists. Nothing captures it at design time, when the engineer still holds the alternatives, the constraints, and the doubts.", "solution": "A seven-stage /cobuilder-architect:design mode writes docs/architecture/designs/<name>/, drafts a decided ADR, and joins pull requests through design/<name>[/<epic-slug>].", "beats": [{"kind": "background", "text": "Submit mode already interviews an author before the PR opens. That is later than the moment the alternatives are still open. Generate mode then reconstructs intent from merged code."}, {"kind": "intuition", "text": "Name the outcome first. Search existing designs by meaning. Interview five topics. Explore. Challenge until rejected options exist. Draft the ADR. Review. Create the first local branch only."}], "alternatives": [{"option": "Build design mode in archkit", "rejected": "The interview, bundle, diagrams, and viewer live here."}, {"option": "Keep the architecture skill optional", "rejected": "A design without a corpus degrades into a chat."}, {"option": "Ask which options they rejected", "rejected": "A rejected option is an outcome of explore and challenge, not an interview input."}, {"option": "Mint a synthetic PR key", "rejected": "story.json and four readers require a real integer pr."}, {"option": "One branch per design", "rejected": "N epics produce N pull requests."}]}, "architecture": {"narration": "Authored source lives in docs/. The bundle is a full rebuild. Architecture modes are self-only. Odyssey keeps --repo. One design lists every ADR it produced, and drift is measured per epic.", "beats": [{"kind": "forces", "text": "story.json keys on an integer pr. The plugin ships no agents, hooks, or MCP servers. cobuilder-factory owns epic decomposition."}, {"kind": "contract", "text": "docs/architecture/designs/<name>/ is the design home. build_adrs.py and build_designs.py rebuild the self bundle only. Submit strips design/ and loads intent.json as the hypothesis."}, {"kind": "boundary", "text": "Design mode does not take --repo, does not push, does not open a PR, and does not decompose epics. A design never enters the timeline until gh pr create returns a number."}]}}, "diagrams": {"1": "C4Container\ntitle cobuilder-architect after design mode\n\nPerson(eng, \"Engineer\", \"Designs, then submits\")\nPerson(rev, \"Reviewer\", \"Reads docs/ and the viewer\")\n\nSystem_Boundary(plugin, \"cobuilder-architect\") {\n  Container(design, \"Design mode\", \"odyssey\", \"Seven stages, self-only\")\n  Container(submit, \"Submit mode\", \"odyssey\", \"Interview, assess, open PR\")\n  Container(odyssey, \"Odyssey five\", \"odyssey\", \"Baseline, generate, view, publish\")\n  Container(arch, \"Architecture six\", \"architecture\", \"Self-only review and decisions\")\n}\n\nSystem_Ext(docs, \"docs/\", \"Authored ADRs, designs, PR write-ups\")\nSystem_Ext(bundle, \".cobuilder-architect/\", \"Derived projections and binary\")\n\nRel(eng, design, \"Names the outcome\")\nRel(design, docs, \"Writes designs/ and a decided ADR\")\nRel(design, arch, \"Stage 3 explore, stage 4 challenge\")\nRel(eng, submit, \"Confirms the PR\")\nRel(submit, docs, \"Reads the design, writes pull-requests/\")\nRel(odyssey, bundle, \"Rebuilds adrs.js and designs.js\")\nRel(rev, bundle, \"Opens the designs view\")\nRel(rev, docs, \"Reviews markdown\")\n"}}, "gate-doc-surfacing": {"goal": {"name": "gate-doc-surfacing", "title": "Surface Gate 3 and Gate 4b docs in the Builds view", "created": "2026-09-01", "outcome": "Gate documents (03-program-design.md, epic-<id>-design.md) are readable from the viewer's Builds view, not just from docs/plans/ or a one-off Artifact publish.", "done_when": ["Gate Rail cards in the Builds view open a sheet showing the gate's doc content", "Epic cards with an approved 4b design show a design-doc chip that opens the same sheet type", "data/index.json carries program_design and epic_design entities projected from docs/plans/<slug>/03-program-design.md and epic-<id>-design.md"], "abort_if": ["a gate's doc content duplicates what 00-status.md's approval-state line already shows well enough that a sheet adds no reading value"], "min_work": {"derived_from": "conversation: colleague session couldn't view Gate 3 progress in the viewer; agreed the Builds Gate Rail is the right home over a new tab or continued artifact publishing", "challenge_stage_run": true, "note": "Design mode ran to completion on 2026-09-01: grounded against ADR-0018/ADR-0020 and the viewer/build_index.py source, interviewed, challenged (four alternatives rejected, recorded in intent.json and ADR-0022), drafted ADR-0022, intent.json, assessment.json, narrative.json, pr-draft.md, and diagrams/level-{1,2,3}.mmd. Reviewed and approved in one round, no material feedback."}, "limits": {"warn_after_rounds": 6, "cutoff_rounds": 10}, "epics": [{"id": "E1", "branch": "design/gate-doc-surfacing", "pr": 19, "state": "open", "note": "shared/build_index.py: add PROGRAM_DESIGN_FIELDS and EPIC_DESIGN_FIELDS projection tuples plus project_program_design/project_epic_design, following the project_fields(source, fields) pattern used by project_goal/project_intent/project_assessment. Parse docs/plans/<slug>/03-program-design.md and epic-<id>-design.md; emit program_design and epic_design entities into data/index.json. Extend feature_gates join entries with a doc reference where one exists."}, {"id": "E2", "branch": "design/gate-doc-surfacing", "pr": 19, "state": "open", "note": "plugins/artifact/viewer/index.html: make gate-rail-grid cards (renderBuildsMainContent, ~line 3249) clickable, opening a gate-doc sheet modeled on openAdrSheet. Add a design-doc chip to renderEpicCard (~line 3282) for epics with an epic_design entity."}], "stage": "decided", "supersedes": null, "adr": "ADR-0022", "adrs": ["ADR-0022", "ADR-0018", "ADR-0020"], "rounds": [{"n": 1, "date": "2026-09-01", "result": "approved", "material_change": false}]}, "intent": {"problem": "Gate 3 program-design docs and Gate 4b epic technical-design docs live at docs/plans/<slug>/*.md, but the viewer's index tracks only adr, design, epic, slice, and pull_request entities. A reviewer who wants to watch a build's Gate 3 progress in the viewer sees nothing — the Gate Rail already shows approval state (00-status.md), but never the document content behind it. The workaround was publishing the doc as a one-off Claude Artifact: readable, but disconnected from docs/plans/, no rebuild hook, and undiscoverable from the viewer itself.", "approach": "Extend shared/build_index.py to project docs/plans/<slug>/03-program-design.md and epic-<id>-design.md into two new index entities, program_design and epic_design, following the existing GOAL_FIELDS/project_fields(source, fields) pattern. Extend joins.feature_gates entries with a doc reference where one exists. In the viewer, make Gate Rail cards clickable, opening a sheet modeled on openAdrSheet, and add a design-doc chip to epic cards that have an approved 4b design.", "alternatives": [{"option": "Add a new top-level 'Plans' or 'Gate Docs' tab in the viewer", "rejected_because": "ADR-0018 decided one lifecycle surface with a derived record index precisely to stop the reading surface count from growing per artifact type. A gate doc is scoped to a build already living in the viewer's Builds view (district: viewer) — a sibling tab duplicates that context instead of joining it."}, {"option": "Parse gate docs ad hoc in the viewer's client-side JS at render time, skipping the index", "rejected_because": "ADR-0018's whole point is that joins get resolved once, in build_index.py, not scattered across client fetches. The viewer is also a single committed HTML file with no direct filesystem access model beyond its bundled data/ scripts (district: viewer) — it cannot read docs/plans/ at render time at all."}, {"option": "Split viewer/index.html into parts now, and add gate docs to the new module structure", "rejected_because": "ADR-0020 decided the viewer-parts split but is explicitly not executed yet (CLAUDE.md: 'treat that ADR as a plan, not as the current shape of the file'). Starting that execution as a side effect of this design is scope creep this design does not own."}, {"option": "Keep publishing gate docs as one-off Claude Artifacts", "rejected_because": "This is the workaround that exposed the gap: no rebuild hook ties it to docs/plans/, so it drifts, and it is not discoverable from the viewer itself — the problem this design exists to fix."}], "authorship": "agent-assisted", "captured": "2026-09-01", "design_name": "gate-doc-surfacing", "out_of_scope": ["a new top-level viewer tab for plans or gate docs", "editing a gate doc from the viewer — read-only sheet only", "changing how 00-status.md's approval state is parsed or displayed", "PDF or standalone-artifact export of a gate doc", "executing ADR-0020's viewer-parts split — this design writes into the current monolithic viewer/index.html, the file that ships today"], "reviewer_focus": ["whether program_design/epic_design entity ids collide with the epic entity's own id scheme", "whether the sheet UX holds up for a long program-design doc", "whether the Gate Rail card / epic chip is discoverable without extra instruction"], "risks": ["a gate doc grows long enough that the sheet reading UX (built for ADR text, a few hundred lines) degrades", "program_design/epic_design entity ids collide with, or get confused with, the existing epic entity's <design>/<epic-id> scoping", "the sheet becomes stale between build_index.py runs the same way the pre-fix Artifact was, if a future gate step forgets to rebuild — mitigated by the just-added viewer-rebuild-per-gate step in implement/skills/build/SKILL.md's approval protocol"], "source": "design", "testing": "Not yet built. shared/build_index.py already has field-projection tests for GOAL_FIELDS/EPIC_FIELDS/etc — the new PROGRAM_DESIGN_FIELDS/EPIC_DESIGN_FIELDS constants and their project_* functions should get the same coverage shape.", "unknowns": ["how large a typical 03-program-design.md or epic-<id>-design.md gets across real features, and whether the sheet needs pagination or truncation", "whether a design with no docs/plans/<slug>/ directory at all (a design never taken to implement mode) should render an empty Gate Rail or hide it entirely"], "why_now": "The prior session's Gate 3 approval loop surfaced this live: the engineer asked to see the design in the viewer, the agent found no entity for it, and improvised an Artifact instead. That workaround is now a repeatable gap, not a one-time surprise, and the viewer's Builds view (renderBuildsMainContent) already renders a Gate Rail and epic cards that are the natural attachment point."}, "assessment": {"verdict": "proceed", "findings": [{"kind": "prediction", "id": "F1", "severity": "low", "title": "New entities follow the existing projection pattern with no new join mechanism", "detail": "program_design and epic_design key on feature_slug and epic_id respectively, both of which the index already carries (joins.feature_gates is keyed by feature_slug; entities.epic already has an id). No new join table is needed — the viewer looks the doc up by a key it already has when rendering the Gate Rail or an epic card.", "cites": "ADR-0018 (record index resolves joins, not per-artifact ad hoc lookups); shared/build_index.py's project_fields pattern", "mitigation": "None needed if the field-projection constants for the two new entities follow GOAL_FIELDS/EPIC_FIELDS exactly, as intent.json's approach specifies."}, {"kind": "prediction", "id": "F2", "severity": "medium", "title": "The sheet UX was built for short structured text, not multi-hundred-line prose", "detail": "openAdrSheet renders ADR frontmatter plus a body that is typically well under a couple hundred lines. A 03-program-design.md or epic-<id>-design.md can run considerably longer once Files/Types/Call stack/Test plan sections are all filled in. Untested at this stage whether the same sheet component reads well at that length.", "cites": "district: viewer; intent.json unknowns", "mitigation": "Confirm during implementation against a real gate doc from this repo's own docs/plans/ tree (e.g. cobuilder-family's 03-program-design.md) before considering the epic done. If unreadable, scroll the sheet body rather than truncate — dropping content silently would misrepresent the record."}, {"kind": "prediction", "id": "F3", "severity": "low", "title": "A design with no docs/plans/<slug>/ directory renders an empty or absent Gate Rail — undecided which", "detail": "Every existing backlog design (maintainable-viewer, inflight-record-store, and now gate-doc-surfacing itself) has no docs/plans/ directory yet, because implement mode hasn't started on them. The Gate Rail today falls back to a hardcoded four-gate placeholder (renderBuildsMainContent's featureGatesMap fallback) when no real gates exist for 'cobuilder-family'. This design does not resolve whether that fallback is still appropriate once real per-design gate data exists for other designs.", "cites": "plugins/artifact/viewer/index.html:3212-3219 (gate fallback literal)", "mitigation": "Scope this to E2's implementation: render nothing for a design with no docs/plans/ directory, rather than the current single hardcoded fallback, which only ever matched one feature."}], "boundary_checks": [{"rule": "No agents, no hooks, no MCP servers in the install surface", "result": "holds", "note": "This adds index-projection code and viewer markup only, both already part of the artifact plugin's existing surface."}, {"rule": "The viewer stays one self-contained committed file (current, pre-ADR-0020-execution shape)", "result": "holds", "note": "E2 edits plugins/artifact/viewer/index.html directly. No viewer/src/ split is introduced by this design."}, {"rule": "docs/ stays authored source; .cobuilder-architect/ stays derived", "result": "holds", "note": "The new entities are derived projections of docs/plans/*.md into data/index.json, the same relationship every other entity in the index already has to its docs/ source."}], "drift": [], "regret_risk": "low", "risk_tier": "low", "stage": "design", "summary": "The projection follows an established pattern exactly (project_fields, GOAL_FIELDS-style tuples) and the viewer attachment point (Gate Rail, epic cards) already exists and already has a sheet precedent (openAdrSheet). The main open risk is UX scale — gate docs are prose, unlike the short structured records the sheet pattern was built for — not architectural fit."}, "narrative": {"landscape": {"narration": "This design closes a visibility gap in the odyssey viewer: a build's Gate 3 program design and Gate 4b epic designs stay invisible to the one surface built to show build progress, so someone reviewing a build has to leave the viewer to read them.", "tagline": "Show the gate document, not just the gate's approval state."}, "problem_solution": {"narration": "The Builds view already shows a Gate Rail of approval state, keyed off 00-status.md. It never carries the document behind each gate. A reviewer who wants to read Gate 3 has no path from the viewer to the doc, and the one-off fix — publishing the doc as a Claude Artifact — drifts from the source and is not discoverable from the viewer itself.", "problem": "Gate 3 and Gate 4b documents exist under docs/plans/<slug>/ but have no entity in the viewer's index, so they never appear in the Builds view no matter how often the bundle rebuilds.", "solution": "Project the two document types into two new index entities, program_design and epic_design, then make the Gate Rail cards and epic cards that already exist in the Builds view open a sheet showing that content.", "beats": [{"kind": "background", "text": "A colleague session tried to open the viewer mid-Gate-3 and found nothing there. The Gate Rail's approval-state chrome was current; the document behind it was not indexed at all."}, {"kind": "intuition", "text": "The Builds view already has the join key a gate doc needs — feature_slug for a program design, epic id for an epic design. Attach the doc to the card that already represents that build, instead of building a new surface to hold it."}], "alternatives": [{"option": "A new top-level Plans tab", "rejected": "ADR-0018 decided one lifecycle surface. A gate doc is scoped to a build already shown in Builds."}, {"option": "Parse gate docs client-side, skipping the index", "rejected": "The viewer is one committed HTML file with no filesystem access beyond its bundled data/ scripts."}, {"option": "Execute ADR-0020's viewer-parts split as part of this design", "rejected": "ADR-0020 is decided but not executed. Starting that execution here is scope this design does not own."}, {"option": "Keep publishing gate docs as one-off Artifacts", "rejected": "No rebuild hook, drifts from docs/plans/, undiscoverable from the viewer — the problem this design fixes."}]}, "architecture": {"narration": "shared/build_index.py gains two field-projection constants and two loader functions, following the same project_fields(source, fields) shape every other entity already uses. The viewer gains a sheet, reusing openAdrSheet's pattern, wired to the Gate Rail and epic cards that renderBuildsMainContent already renders.", "beats": [{"kind": "forces", "text": "The viewer stays one self-contained file today, so this attaches to plugins/artifact/viewer/index.html directly, not to a future viewer/src/ split."}, {"kind": "contract", "text": "program_design keys on feature_slug, matching joins.feature_gates. epic_design keys on epic id, matching entities.epic. No new join table."}, {"kind": "boundary", "text": "Read-only. No editing a gate doc from the viewer, no change to how 00-status.md's approval state itself is parsed or displayed."}]}}, "diagrams": {"1": "C4Container\n    title Gate doc surfacing — program and epic design docs reach the Builds view\n\n    Person(engineer, \"Engineer\", \"Reads a build's gate rail and backlog lane in the viewer\")\n\n    Container_Boundary(docsdir, \"docs/plans/<slug>/ — authored\") {\n        Container(status, \"00-status.md\", \"Markdown\", \"Gate approval state, parsed by resolve_feature_gates()\")\n        Container(progdesign, \"03-program-design.md\", \"Markdown\", \"Gate 3 program-design doc, one per feature slug\")\n        Container(epicdesign, \"epic-<id>-design.md\", \"Markdown\", \"Gate 4b epic technical-design doc, one per multi-slice epic\")\n    }\n\n    Container_Boundary(shared, \"shared/ — index build\") {\n        Container(buildindex, \"build_index.py\", \"Python\", \"project_fields() projects program_design and epic_design entities\")\n    }\n\n    ContainerDb(indexjson, \"data/index.json\", \"JSON\", \"joins.feature_gates carries a doc-reference field per gate; program_design and epic_design entities keyed by feature_slug and epic id\")\n\n    Container_Boundary(viewerdir, \"plugins/artifact/viewer/\") {\n        Container(viewer, \"index.html\", \"Single-file HTML/JS\", \"renderBuildsMainContent(), gate-rail-grid, renderEpicCard()\")\n        Container(sheet, \"Gate/epic design sheet\", \"JS modal\", \"Read-only, modeled on openAdrSheet()\")\n    }\n\n    Rel(engineer, viewer, \"Opens the Builds view\")\n    Rel(status, buildindex, \"Gate approval state parsed by resolve_feature_gates()\")\n    Rel(progdesign, buildindex, \"Projected as program_design entity\")\n    Rel(epicdesign, buildindex, \"Projected as epic_design entity\")\n    Rel(buildindex, indexjson, \"Rebuilds joins.feature_gates plus the two new entities\")\n    Rel(indexjson, viewer, \"Loaded as window.INDEX\")\n    Rel(viewer, sheet, \"Gate card or design-doc chip click opens\")\n    Rel(sheet, engineer, \"Shows gate doc or epic design content, read-only\")\n", "2": "sequenceDiagram\n    participant Author as Engineer (authoring)\n    participant Status as 00-status.md\n    participant ProgDoc as 03-program-design.md\n    participant EpicDoc as epic-<id>-design.md\n    participant BuildIndex as build_index.py\n    participant IndexJson as data/index.json\n    participant Viewer as viewer/index.html\n    participant Sheet as design-doc sheet (openAdrSheet pattern)\n    participant Reader as Engineer (reading)\n\n    Author->>Status: Marks Gate 3 / Gate 4b approved\n    Author->>ProgDoc: Writes program-design doc\n    Author->>EpicDoc: Writes epic technical-design doc\n\n    Note over BuildIndex: Index rebuild (odyssey / implement modes call this)\n    BuildIndex->>Status: resolve_feature_gates() parses gate approval state\n    BuildIndex->>ProgDoc: project_fields(source, fields) reads doc if present\n    BuildIndex->>EpicDoc: project_fields(source, fields) reads doc if present\n    BuildIndex->>IndexJson: Writes program_design entity keyed by feature_slug\n    BuildIndex->>IndexJson: Writes epic_design entity keyed by epic id\n    BuildIndex->>IndexJson: Writes joins.feature_gates with doc-reference field per gate\n\n    Reader->>Viewer: Opens Builds view\n    Viewer->>IndexJson: Reads window.INDEX\n    Viewer->>Viewer: renderBuildsMainContent() renders gate-rail-grid\n    Viewer->>Viewer: renderEpicCard() adds design-doc chip when epic_design is approved\n\n    Reader->>Viewer: Clicks a gate card in gate-rail-grid\n    Viewer->>Sheet: openGateDesignSheet(feature_slug, gate_n)\n    Sheet->>IndexJson: Looks up joins.feature_gates doc reference\n    Sheet-->>Reader: Renders program-design doc content, read-only\n\n    Reader->>Viewer: Clicks a design-doc chip on an epic card\n    Viewer->>Sheet: openGateDesignSheet(epic_id, scope=\"epic\")\n    Sheet->>IndexJson: Looks up epic_design entity by epic id\n    Sheet-->>Reader: Renders epic technical-design doc content, read-only\n", "3": "classDiagram\n    class project_fields {\n        +project_fields(source, fields) dict\n    }\n\n    class ProgramDesignEntity {\n        <<index entity>>\n        +feature_slug string\n        +path string\n        +fields dict\n    }\n\n    class EpicDesignEntity {\n        <<index entity>>\n        +epic_id string\n        +path string\n        +fields dict\n        +approved bool\n    }\n\n    class resolve_feature_gates {\n        +resolve_feature_gates(slug) list~GateEntry~\n    }\n\n    class GateEntry {\n        +n int\n        +name string\n        +state string\n        +doc_ref string\n    }\n\n    class BuildIndexScript {\n        <<shared/build_index.py>>\n        +collect_program_designs() dict\n        +collect_epic_designs() dict\n        +build_index() void\n    }\n\n    class IndexJson {\n        <<data/index.json>>\n        +program_design dict\n        +epic_design dict\n        +joins.feature_gates list~GateEntry~\n    }\n\n    class renderBuildsMainContent {\n        <<viewer function>>\n        +renderBuildsMainContent(main) void\n    }\n\n    class renderEpicCard {\n        <<viewer function>>\n        +renderEpicCard(epic) string\n    }\n\n    class openAdrSheet {\n        <<existing viewer function>>\n        +openAdrSheet(id) void\n    }\n\n    class openGateDesignSheet {\n        <<new viewer function>>\n        +openGateDesignSheet(key, scope) void\n    }\n\n    BuildIndexScript --> project_fields : uses for both entities\n    BuildIndexScript --> resolve_feature_gates : calls, then attaches doc_ref\n    resolve_feature_gates --> GateEntry : produces list of\n    project_fields --> ProgramDesignEntity : produces\n    project_fields --> EpicDesignEntity : produces\n    BuildIndexScript --> IndexJson : writes program_design, epic_design, joins.feature_gates\n    GateEntry --> IndexJson : embedded in joins.feature_gates\n\n    renderBuildsMainContent --> IndexJson : reads window.INDEX\n    renderBuildsMainContent --> renderEpicCard : calls per epic\n    renderEpicCard --> EpicDesignEntity : reads approved flag for chip\n    renderBuildsMainContent --> openGateDesignSheet : gate-card click handler\n    renderEpicCard --> openGateDesignSheet : design-doc chip click handler\n    openGateDesignSheet ..> openAdrSheet : modeled on\n\n    note for openGateDesignSheet \"Read-only sheet, scoped by feature_slug\\nfor a gate doc or epic id for an epic design doc\"\n"}, "pr_draft": "## Problem\n\nGate 3 program-design docs (`03-program-design.md`) and Gate 4b epic\ntechnical-design docs (`epic-<id>-design.md`) live under\n`docs/plans/<slug>/`, but the viewer's index tracks only five entity\ntypes — `adr`, `design`, `epic`, `slice`, `pull_request`. A build's Gate\nRail in the Builds view already shows approval state, read from\n`00-status.md`, but the document behind each gate never appears. A\ncolleague session mid-Gate-3 hit this directly: asked the viewer to show\nthe design, found nothing indexed, and worked around it by publishing the\ndoc as a one-off Claude Artifact.\n\n## Why this approach\n\nAdd two new index entities, `program_design` and `epic_design`, projected\nfrom `docs/plans/<slug>/*.md` by `shared/build_index.py`, following the\nsame `project_fields(source, fields)` pattern every other entity already\nuses (`GOAL_FIELDS`, `EPIC_FIELDS`, `INTENT_FIELDS`, `ASSESSMENT_FIELDS`).\nKey `program_design` on `feature_slug`, matching `joins.feature_gates`.\nKey `epic_design` on epic id, matching `entities.epic`. No new join table.\n\nIn the viewer, make the Gate Rail cards in `renderBuildsMainContent`\nclickable, opening a read-only sheet modeled on the existing\n`openAdrSheet`. Add a design-doc chip to an epic card that has an approved\n4b design, opening the same sheet type scoped to that epic.\n\n## Alternatives considered\n\n- **A new top-level Plans tab** — rejected because ADR-0018 decided one\n  lifecycle surface with a derived record index specifically to stop the\n  reading-surface count growing per artifact type. A gate doc is scoped to\n  a build already shown in the Builds view.\n- **Parse gate docs client-side at render time, skipping the index** —\n  rejected because the viewer is one committed HTML file with no\n  filesystem access beyond its bundled `data/*.js` scripts, and because\n  ADR-0018's whole point is resolving joins once, in `build_index.py`.\n- **Execute ADR-0020's viewer-parts split as part of this design** —\n  rejected because ADR-0020 is decided but explicitly not executed yet.\n  Starting that execution as a side effect here is scope this design does\n  not own.\n- **Keep publishing gate docs as one-off Claude Artifacts** — rejected\n  because it is the workaround that exposed the gap: no rebuild hook ties\n  it to `docs/plans/`, so it drifts, and it is not discoverable from the\n  viewer itself.\n\n## Out of scope\n\n- A new top-level viewer tab.\n- Editing a gate doc from the viewer — read-only sheet only.\n- Changing how `00-status.md`'s approval state is parsed or displayed.\n- PDF or standalone-artifact export of a gate doc.\n- Executing ADR-0020's viewer-parts split.\n\n## Risks\n\n- A gate doc can run considerably longer than the ADR text the sheet\n  pattern was built for. Untested whether the same sheet component reads\n  well at that length.\n- `program_design`/`epic_design` entity ids could be confused with the\n  existing epic entity's `<design>/<epic-id>` scoping if not kept\n  distinct.\n- The sheet goes stale if a future gate step skips the bundle rebuild —\n  mitigated by the viewer-rebuild-per-gate step already added to\n  `implement/skills/build/SKILL.md`'s approval protocol.\n\n## How this was tested\n\nNo code changes yet; this design writes `docs/` artifacts only.\nVerification for this pass: `goal.json` parses, `build_index.py` runs\nclean and picks up the new backlog design, and the existing 312-test\npackaging suite passes unaffected. Implementation-time verification is\ndescribed in `goal.json.done_when`.\n\n## Where to focus\n\n- Whether the sheet UX holds up for a real, long program-design doc — try\n  it against this repo's own `docs/plans/cobuilder-family/03-program-design.md`.\n- Whether `program_design`/`epic_design` entity ids collide with, or read\n  as confusable with, the epic entity's own id scheme.\n- Whether the Gate Rail's current hardcoded four-gate fallback for a\n  design with no `docs/plans/<slug>/` directory still makes sense once\n  real per-design gate data exists for designs other than\n  `cobuilder-family`.\n\nThe author flagged these parts as not fully understood:\n- How large a typical gate doc gets across real features in practice —\n  unverified beyond this repo's own examples.\n\n---\n\nAuthorship: agent-generated.\n"}, "inflight-record-store": {"goal": {"name": "inflight-record-store", "title": "A record store for in-flight pull requests", "created": "2026-08-25", "outcome": "A reader on the main branch sees every piece of in-flight work across all open pull requests, and no pull request owner hits a merge conflict caused by that view.", "done_when": [], "abort_if": [], "min_work": {"derived_from": "collect_pull_requests() in shared/build_index.py reads data/story.json, which holds narrated, merged pull requests only. Eight epics in goal.json files point at pull request 11, which is not a pull_request entity, so refine_epic_status() cannot derive its state and leaves a hardcoded placeholder. A daily agent that pulls every branch and writes one consolidated view onto main guarantees a merge conflict for every pull request owner, because each of them touches the same generated file. File-based single-document storage cannot carry concurrent in-flight state. This constraint makes the work a program, not a single fix. The role model is beads (bd), which stores one record per file with append-only semantics and a defined merge strategy.", "challenge_stage_run": false, "note": "Stage 0 and stage 1 grounding did not run. Stages 2 through 7 are deliberately deferred. This design is a backlog entry, not an approved design. It carries no intent.json, narrative.json, assessment.json, or diagrams, and it must not be implemented until design mode runs to completion."}, "limits": {"warn_after_rounds": 3, "cutoff_rounds": 6}, "epics": [{"id": "E1", "branch": null, "pr": null, "state": "planned", "note": "Open pull requests become entities. collect_pull_requests() merges gh pr list --state all metadata over the narrated story.json entities. An open pull request gets an entity with state: \"open\" and a narrated: false flag. This removes the placeholder in refine_epic_status(). It reads metadata only, checks out no branch, and creates no conflict. This is the tracer bullet, and it is useful on its own. It does not depend on E2, E3, or E4, and can ship alone."}, {"id": "E2", "branch": null, "pr": null, "state": "planned", "note": "A record store with a merge strategy. One file per record, append-only, with a defined resolution rule for a concurrent write. Modelled on beads. This epic decides the storage shape and nothing else."}, {"id": "E3", "branch": null, "pr": null, "state": "planned", "note": "Cross-branch collection without a conflict. Records written by a session on a branch reach the shared view without any branch writing a shared generated file."}, {"id": "E4", "branch": null, "pr": null, "state": "planned", "note": "The active-work view. The viewer renders in-flight work beside merged history, so a reader sees one timeline rather than two."}], "stage": "backlog", "supersedes": null, "adr": null, "adrs": ["ADR-0018"], "rounds": []}}, "lean-bundle-diffs": {"goal": {"name": "lean-bundle-diffs", "title": "Stop committing per-PR diff dumps into the bundle", "created": "2026-08-26", "outcome": "A fresh clone of this repo is not weighed down by every merged PR's full diff text, and the viewer still shows a diff for any PR a reader opens.", "done_when": [], "abort_if": [], "min_work": {"derived_from": "data/diffs-pr{N}.js under .cobuilder-architect/ is a per-PR export of extract_diffs.py's output, committed today the same way story.js and adrs.js are. Measured on 2026-08-26: the repo's clone size is ~40 MB, and the largest single files are diffs-pr11.js (6.4 MB) and several more in the hundreds of KB to low MB range, per-PR and permanent. Unlike the narrative and ADRs, a diff is fully reproducible at any time from git diff <merge-base>..<head> as long as history is not rewritten, so committing it buys nothing a live git command could not supply on demand.", "challenge_stage_run": false, "note": "Stage 0 and stage 1 grounding did not run. Stages 2 through 7 are deliberately deferred. This design is a backlog entry, not an approved design. It carries no intent.json, narrative.json, assessment.json, or diagrams, and it must not be implemented until design mode runs to completion."}, "limits": {"warn_after_rounds": 3, "cutoff_rounds": 6}, "epics": [{"id": "E1", "branch": null, "pr": null, "state": "planned", "note": "Decide the replacement shape: the viewer reads a diff by running git diff against the PR's recorded commit SHAs at serve time (view mode already runs from inside the repo), versus keeping diffs-pr{N}.js exactly as it is today but gitignoring it, regenerating it from git on demand the way exports/branch-*/diff.json already works for generate mode. Either removes the committed weight; they differ in whether a served bundle still needs a live git checkout next to it."}, {"id": "E2", "branch": null, "pr": null, "state": "planned", "note": "Whichever shape E1 picks, implement it in extract_diffs.py and, if the viewer starts requesting diffs at view time instead of reading a static file, in artifact's serve_bundle.py. Update verify_bundle.py's expectations accordingly."}, {"id": "E3", "branch": null, "pr": null, "state": "planned", "note": "Migrate the existing committed bundles (self, and the two fixture bundles) so history stops growing: remove the checked-in diffs-pr{N}.js files, or move them under .gitignore, per E1's decision. This does not touch story.json's authored fields, so it is a bundle-file change, not a schema migration."}], "stage": "backlog", "supersedes": null, "adr": null, "adrs": [], "rounds": []}}, "maintainable-viewer": {"goal": {"name": "maintainable-viewer", "title": "The viewer becomes parts, templates, and mode modules", "created": "2026-08-24", "outcome": "An engineer changes one view mode of the bundle viewer by opening one file of a few hundred lines, and the file that ships is still one self-contained HTML page that publishes as an Artifact unchanged.", "done_when": ["viewer/index.html is produced by build_viewer.py from ordered parts under viewer/src/, and a test fails when the committed output does not equal a fresh build", "no part exceeds roughly 400 lines, and each of the five view modes lives in its own part", "the rail-item, empty-card, and empty-detail fragments have one definition each, instead of 4, 16, and 18 copies", "the 50 scattered mode-predicate calls collapse into one mode registry, and adding a sixth mode touches one new part plus one registry entry", "export_artifact.py matches named markers the parts emit on purpose, instead of incidental literals, and publishing a PR still succeeds byte-for-byte equivalently", "the five modes render identically before and after, proven by measurement in a browser rather than by reading the code"], "abort_if": ["the single IIFE proves not separable, because sections close over shared state in a way that ordered concatenation cannot preserve without rewriting the state model", "ordered concatenation turns out to be insufficient and the build needs real dependency resolution, which would reopen the bundler option ADR-0020 rejected"], "min_work": {"derived_from": "4917 measured lines (881 CSS, 3872 JS, 145 functions, 50 mode-predicate calls, 45 innerHTML blocks, 0 templates), 4 related ADRs, 1 bounded context, 35 existing banner-comment sections", "challenge_stage_run": false, "note": "Stage 0 and stage 1 grounding ran on 2026-08-24 and produced the measurements above. Stages 2 through 7 are deliberately deferred at the engineer's request. This design is a backlog entry, not an approved design. It carries no intent.json, narrative.json, assessment.json, or diagrams, and it must not be implemented until design mode runs to completion."}, "limits": {"warn_after_rounds": 3, "cutoff_rounds": 6}, "epics": [{"id": "E1", "branch": null, "pr": null, "state": "planned", "note": "The build exists and is guarded. build_viewer.py concatenates ordered parts under viewer/src/ into the committed viewer/index.html, and a test rebuilds from the parts and fails on any difference. The first split is mechanical only, cut at the file's own 35 banner comments, with no line rewritten. This epic is the tracer bullet: it proves or disproves that the single IIFE separates by concatenation alone, which is the abort condition the whole design rests on."}, {"id": "E2", "branch": null, "pr": null, "state": "planned", "note": "The exporter seam becomes declared. export_artifact.py stops matching incidental literals and matches named markers the parts emit deliberately. Today it hard-errors with not-found-verbatim when a literal moves, so the publish pipeline breaks silently under any refactor until somebody publishes. This must land before the parts are rewritten, not after, or every later epic risks breaking publishing without a test noticing."}, {"id": "E3", "branch": null, "pr": null, "state": "planned", "note": "One definition per fragment. A template layer replaces the 45 innerHTML string blocks, and the rail-item, empty-card, and empty-detail fragments collapse from 4, 16, and 18 copies to one each. The viewer uses no template element today, so the mechanism is a design choice this epic makes and does not inherit."}, {"id": "E4", "branch": null, "pr": null, "state": "planned", "note": "Each mode owns its own part. The five view modes stop interleaving: the 50 scattered mode-predicate calls collapse into one registry, and renderContextsMainContent, renderBuildsMainContent, and renderMainContent stop being three functions of over 200 lines that live beside each other. Adding a sixth mode becomes one new part plus one registry entry."}], "stage": "superseded", "supersedes": null, "adr": "ADR-0020", "adrs": ["ADR-0020", "ADR-0001", "ADR-0018", "ADR-0019"], "rounds": [], "superseded_by": "react-viewer", "superseded_note": "Superseded by react-viewer (ADR-0023) on 2026-09-07. ADR-0023 answers the same question with TypeScript and React compiled by Vite, instead of ordered parts concatenated by a Python script. This design was never executed, so no work is lost."}}, "plugin-split": {"goal": {"name": "plugin-split", "title": "Five sibling plugins, with the bundle as the only seam", "created": "2026-08-20", "outcome": "A user installs one stage of the architecture lifecycle without the other three, and four independently-installed plugins write into one bundle without a stale copy destroying authored or paid content.", "done_when": ["five plugin manifests validate, and cobuilder-full-lifecycle installs the other four", "shared/ is vendored by symlink and an installed copy resolves it from its own cache", "require_compatible() gates every script that writes into a bundle", "bundle.json carries min_reader_schema and a generators map instead of one scalar"], "abort_if": ["the marketplace symlink dereference does not cover a directory of Python that a skill later runs, and the copy-before-publish fallback proves worse than staying one plugin"], "min_work": {"derived_from": "6 districts (skills, scripts, commands, viewer, docs, .cobuilder-architect), 4 related ADRs, 1 boundary rule on install surface", "alternatives_explored": 5, "boundary_rules_checked": true, "challenge_stage_run": true}, "limits": {"warn_after_rounds": 3, "cutoff_rounds": 6}, "epics": [{"id": "E1", "branch": "design/design-mode", "pr": 11, "state": "open", "note": "One plugin becomes five. The whole packaging split: the mode renames inside today's single plugin, the deleted duplicate explore-design command, the 33 cross-pillar references, the five manifests, and the two ports. The rename is a rotation, not a split: odyssey submit becomes cobuilder-pr:generate, and the old odyssey generate, which narrates merged history, becomes cobuilder-pr:review. Four slices."}, {"id": "E2", "branch": "design/design-mode", "pr": 11, "state": "open", "note": "Shared code survives an install. Prove the marketplace symlink dereference, then vendor the four bundle modules and the two shared skills. One slice, because it is a spike whose result decides whether the rest of the design stands. goal.json.abort_if names its failure."}, {"id": "E3", "branch": "design/design-mode", "pr": 11, "state": "open", "note": "The seam is version-safe. require_compatible(), min_reader_schema, the generators map, bundle format 3, and schema 1.3, so two plugins at different versions cannot corrupt one bundle. Two slices."}, {"id": "E4", "branch": "design/design-mode", "pr": 11, "state": "open", "note": "The record index. build_index.py replaces the two projection scripts, emits every entity with a stable id, and resolves every join including an ADR to its pull request. Two slices."}, {"id": "E5", "branch": "design/design-mode", "pr": 11, "state": "open", "note": "One lifecycle surface. The Decisions, Contexts, and Builds modes, the Backlog lane, and moving generated pages out of the foreign directory into the bundle. Two slices (10, 11)."}, {"id": "E6", "branch": "design/design-mode", "pr": 11, "state": "open", "note": "The reply channel. The append-only ledger and its projection, the anchor computed from the live DOM, the write endpoint, and the background wake command. Three slices (12, 13, 14)."}, {"id": "E7", "branch": null, "pr": null, "state": "planned", "note": "Threads read as conversations. The drawer renders a reply under the comment it answers. Deferred past E6 on purpose: E6 ships the record shape, so this epic adds no migration and carries no slice yet."}, {"id": "E8", "branch": "rename-plugins-drop-cobuilder-prefix", "pr": 17, "state": "merged", "note": "The cobuilder- prefix drops from the four non-umbrella plugins named in E1's table (cobuilder-architect, cobuilder-pr, cobuilder-artifact, cobuilder-implement become architect, pr, artifact, implement), since it duplicates the marketplace repo's own name. cobuilder-full-lifecycle keeps its prefix, being the umbrella the repo's own name already carries. Merged as PR #17, then a same-epic follow-up (uncommitted at the time this entry was written) fixes a second-order bug the rename introduced: two of the four renamed plugins (implement, artifact) already shipped a skill folder named after themselves, and once the plugin took that same name too, Skill() resolution inside Claude Code broke -- reproduced directly, not environment-specific. Fixed by renaming the colliding skill folders (implement's skill to build, its command to start; artifact's skill to cobuilder-artifacts) and, for consistency, cobuilder-full-lifecycle's orientation skill to cobuilder-full. See ADR-0016's addendum."}], "stage": "implemented", "supersedes": null, "adr": "ADR-0016", "adrs": ["ADR-0016", "ADR-0017", "ADR-0015", "ADR-0006"], "rounds": [{"n": 1, "changed": true, "feedback_class": "material"}]}, "intent": {"problem": "One plugin carries the whole architecture lifecycle. Its four skills, thirteen commands, and twenty-two scripts serve four separate jobs, and a user who wants one job installs all four. The names have drifted with the scope: the same short words mean different things across the two skill families, and CLAUDE.md now carries a vocabulary table to keep them apart. A vocabulary table is a symptom. The words collide because one install surface holds four bounded contexts.", "approach": "Five sibling plugins in one marketplace repository, none nested inside another: cobuilder-architect, cobuilder-pr, cobuilder-artifact, cobuilder-implement, and cobuilder-full-lifecycle, which ships one orientation skill and lists the other four as dependencies. No plugin reads or imports another plugin's files, though a plugin may hand off to another plugin's mode by name. They integrate only by reading and writing the bundle directory, which becomes a Published Language rather than a shared kernel. Shared Python and shared skills travel by a marketplace-level shared/ directory, symlinked into each plugin and dereferenced into its own cache at install. The compatibility gate moves out of skill prose into require_compatible(), a function in the module every plugin vendors, and bundle.json carries the floor that gate reads.", "alternatives": [{"option": "Keep one plugin and organise internally with directories and modes", "rejected": "A directory is not installable. The install surface is the unit a user chooses, so a user who wants only PR narration still takes the review corpus, the viewer, and the paid-art pipeline."}, {"option": "Two plugins, one per pillar, with the viewer duplicated into both", "rejected": "Both pillars write projections the one viewer reads. Two copies drift, and the Designs toggle then renders differently depending on which plugin last refreshed the file."}, {"option": "Let plugins reach each other's scripts through a shared path", "rejected": "Not possible. A cached plugin cannot read outside its own directory, and CLAUDE_PLUGIN_ROOT resolves only to that plugin's own cache."}, {"option": "Abandon the plugin format and ship one cloned repository with entry-point scripts", "rejected": "It removes version skew by removing the install surface, and the install surface is the product."}, {"option": "Symlink the shared modules and add one scalar version comparison per entry point", "rejected": "A scalar cannot express a sequenced ladder with per-step touches sets. Two copies can agree on the number and still disagree on what a step may change, which is false confidence rather than a gate."}, {"option": "A write-log ledger as the compatibility mechanism", "rejected": "It records a mismatch after the mismatch is on disk. Kept in part: its useful half is the plugin identity, which survives as the generators map."}], "authorship": "agent-assisted", "captured": "2026-08-20", "design_name": "plugin-split", "doubts": ["The symlink dereference is documented for sharing files within a marketplace, and the worked example is a meta-plugin's skills/ directory. It is not stated for a directory of Python that a skill later runs through CLAUDE_PLUGIN_ROOT.", "The one-tag release discipline is policy. Nothing in the install mechanism enforces it, so the gate has to hold on its own."], "source": "design", "why_now": "The pieces the split needs are all present and none of them are wired. The architecture skill merged in. Design mode and cobuilder-implement are designed and joined through intent.json. The viewer already has a Designs and Pull-requests toggle, so it already reads projections written by what would become two different plugins, and neither writer knows the other exists. The seam is real before the split, which is why the split is a packaging change rather than a rewrite."}, "assessment": {"verdict": "proceed", "findings": [{"kind": "skill-gap", "id": "F1", "severity": "high", "title": "Architecture design mode does not know design directories exist", "detail": "skills/architecture/SKILL.md's Design Mode section names one output: an ADR markdown document, optionally with an HTML version. The design directory — goal.json, intent.json, narrative.json, assessment.json, diagrams/ — came from the odyssey design mode and is specified in skills/odyssey/references/design-mode.md. Session decision 3 folds odyssey design into the architect pillar, but the architecture skill was never given that responsibility. Running the mode therefore produced two well-formed ADRs and no design at all. The Designs view stayed empty because nothing in the mode it ran was ever told to fill it.", "cites": "skills/architecture/SKILL.md, Design Mode, Output", "mitigation": "Design mode's Output section must name the design directory as a first-class output alongside the ADR, and reference the seven stages in design-mode.md rather than stopping at the corpus chain. This is merge debt from folding the two skills together, not a new feature."}, {"kind": "skill-gap", "id": "F2", "severity": "high", "title": "narrative.json is the only design artifact with no projection and no validation", "detail": "build_designs.py projects goal, intent, and assessment through explicit field tuples (GOAL_FIELDS, INTENT_FIELDS, ASSESSMENT_FIELDS) and validates their shape. narrative.json is attached raw at line 277 with one isinstance check. Its four-level structure — landscape, problem_solution, architecture, file_changes — is written down nowhere: not in the script, not in the architecture skill, not in a template. An author has to read design-mode/narrative.json and infer the shape. A missing or misshapen level fails silently in the viewer rather than loudly in the build.", "cites": "scripts/build_designs.py:277, viewer/index.html:816", "mitigation": "Give narrative.json a NARRATIVE_FIELDS projection and a per-level check, the same treatment the other three artifacts already get. Add the level shape to the design-mode reference so it can be authored without reverse-engineering an example."}, {"kind": "skill-gap", "id": "F3", "severity": "medium", "title": "verify_bundle checks PRs level by level and designs file-by-existence", "detail": "check_designs() returns ok when data/designs.js parses as an object assignment. It never looks inside a design. A design carrying only goal.json passes as ok, which is exactly what happened here. The per-PR checks verify each of the four narrative levels, each asset, and each diagram individually. Two artifact families feed the same four-level viewer under two completely different standards of proof.", "cites": "scripts/verify_bundle.py:215-226", "mitigation": "Extend check_designs to report per-design completeness in the same vocabulary the PR checks use, with narrative levels required and intent, assessment, and diagrams optional."}, {"kind": "skill-gap", "id": "F4", "severity": "low", "title": "The corpus path in the skill body does not match the corpus on disk", "detail": "SKILL.md and corpus-index.md both reference corpus/principles/... The files live at references/corpus/principles/... A first read from the skill base directory finds nothing.", "cites": "skills/architecture/SKILL.md, Design Mode corpus chain", "mitigation": "Make the paths relative to the skill base directory, or state the base the paths are relative to."}, {"kind": "prediction", "id": "F5", "severity": "high", "title": "The compatibility gate is only as good as its least-updated vendored copy", "detail": "require_compatible() lives in a module each plugin vendors. A plugin forked before the function existed carries no gate, and the safety property collapses without a signal. The one-tag release discipline narrows this to cross-tag skew but does not close it, because nothing in the install mechanism enforces a shared tag.", "cites": "ADR-0017", "mitigation": "Have the writer record its own key in the generators map on every write. A bundle whose generators map holds a plugin that never advanced its key is then visible evidence of an ungated writer, rather than an invisible one."}, {"kind": "prediction", "id": "F6", "severity": "medium", "title": "Neither ADR can reach approved, because the context they map to does not exist", "detail": "ADR-0016 and ADR-0017 both anchor maps_to at context cobuilder-packaging. docs/architecture/contexts/ is empty, so there is no boundary.yaml carrying the invariant either record establishes. The decision-records standard requires that anchor.", "cites": "ADR-0016, ADR-0017, Maps to", "mitigation": "Run /cobuilder-architect:describe for cobuilder-packaging before either record leaves tentative. That is epic E5."}], "boundary_checks": [{"rule": "No agents, no hooks, no MCP servers in the install surface", "result": "holds", "note": "The split adds manifests and symlinks only."}, {"rule": "Authored source lives in docs/, derived projections in the bundle", "result": "holds", "note": "shared/ is authored source at the marketplace root, outside both."}, {"rule": "Architecture modes are self-only and refuse a foreign target", "result": "holds", "note": "The split does not move any mode across that line."}], "drift": [{"kind": "drift", "title": "Two design modes still coexist", "detail": "skills/odyssey/references/design-mode.md and skills/architecture/SKILL.md both define a design mode. Decision 3 folds one into the other. Until that lands, which mode a user gets depends on which command they type, and only one of them writes a design directory."}], "regret_risk": "medium", "risk_tier": "high", "stage": "design", "summary": "The split is sound and the compatibility gate is the load-bearing half. Two findings are about the change itself. Four are about the skill mode that produced it: running /cobuilder-architect:design against this design surfaced that architecture's design mode writes an ADR and nothing else, so every design-directory artifact the viewer renders had to be written by hand afterwards."}, "narrative": {"landscape": {"tagline": "One install surface, four jobs.", "narration": "The plugin grew until one install carried the whole architecture lifecycle: design a change, build it, submit and narrate the pull request, render the result. Four jobs, one manifest. The first sign was not a bug. It was a vocabulary table appearing in CLAUDE.md to stop the same short words meaning two things, because review meant one thing in the architecture skill and another in the odyssey skill. This design splits the install surface along the seam the words were already drawing."}, "problem_solution": {"problem": "One plugin holds four bounded contexts. A user who wants pull-request narration installs the review corpus, the viewer, and the paid-art pipeline as well. The names collide because nothing in the packaging keeps the contexts apart, so the prose has to.", "solution": "Five sibling plugins in one marketplace repository, integrating only through the bundle directory on disk. No plugin reads or imports another plugin's files, though a plugin may hand off to another plugin's mode by name. The bundle becomes a Published Language: its shape is documented and versioned, and it belongs to no plugin that writes into it.", "narration": "The split is easy to state and the cost is easy to miss. Today one plugin writes the bundle, so the bundle cannot disagree with itself. Four plugins can be four different versions on one machine, and each carries its own vendored copy of the code that decides what a bundle is allowed to contain. That copy is the whole risk, because the bundle holds authored prose, paid images, and paid audio that no rerun can replace.", "beats": [{"kind": "background", "text": "A cached plugin cannot read outside its own directory. CLAUDE_PLUGIN_ROOT resolves to one plugin's own cache and nothing above it. The dependencies field guarantees co-installation, not file access. So shared code must be copied, not referenced."}, {"kind": "discovery", "text": "The refusal posture already exists. migrate_bundle.py exits with status 1 on a bundle_format or schema_version newer than it knows, and names the remediation. What was missing was not the idea of refusing."}, {"kind": "discovery", "text": "Three writers bypass it entirely. extract_story.py overwrites meta.schema_version with its own compiled constant, and export_artifact.py and _manifest.py stamp the same constant. None of them reads bundle.json first. Today that is safe only because the skill prose runs migrate first."}, {"kind": "turn", "text": "Prose in one plugin's SKILL.md cannot bind another plugin. Across a plugin boundary the invariant has to be code, so the gate moves into require_compatible() in the module every plugin vendors."}, {"kind": "turn", "text": "The bundle carries the floor, not the plugin. A plugin stops asking whether its own version looks recent and asks the bundle what the bundle demands. That is the only form of the check that still works when nobody can enumerate the readers."}], "alternatives": [{"option": "Keep one plugin, organise internally", "rejected": "A directory is not installable."}, {"option": "Two plugins, viewer duplicated into both", "rejected": "Both pillars write projections one viewer reads. Two copies drift."}, {"option": "Reach a sibling plugin's files at a shared path", "rejected": "Not possible after install. The docs are explicit."}, {"option": "Abandon the plugin format, ship a cloned repo", "rejected": "It removes skew by removing the install surface, which is the product."}, {"option": "Symlink plus one scalar version compare", "rejected": "A scalar cannot express a sequenced ladder with per-step touches sets. False confidence."}, {"option": "A write-log ledger as the mechanism", "rejected": "It reports the mismatch after it is written. Kept as the generators map."}]}, "architecture": {"narration": "Three plugins write projections into one versioned directory, one reads all of them, and no arrow runs from any plugin to any other. That absence is the design. cobuilder-implement is the exception in kind, not in mechanism: it hands off through a git branch and a real pull request, which is still a file-and-state seam rather than a call.", "beats": [{"kind": "forces", "text": "The install surface is fixed: no agents, no hooks, no MCP servers. There is no CI, no test suite, and no package manager, so any gate has to be runtime code rather than a build check."}, {"kind": "boundary", "text": "shared/ sits at the marketplace root and is not itself a plugin. Each plugin symlinks what it needs, and the documented dereference copies the target content into that plugin's own cache at install. Every plugin ships byte-identical code and no plugin reads outside itself at runtime."}, {"kind": "boundary", "text": "bundle.json gains min_reader_schema, the schema version of the newest migration that has ever touched this bundle. require_compatible() refuses when that floor exceeds the caller's own compiled SCHEMA_VERSION, before any ladder step runs."}, {"kind": "consequence", "text": "generator_version becomes generators, a map keyed by plugin. One scalar written from the running plugin's own manifest is accurate with one writer and silently wrong with four."}, {"kind": "open", "text": "The symlink dereference is documented for a meta-plugin's skills/ directory, not for a directory of Python a skill later runs. Install a two-plugin draft from a local marketplace and read the cache before this leaves tentative. The fallback is a copy step before publish."}]}}}, "react-viewer": {"goal": {"name": "react-viewer", "title": "The bundle viewer becomes a TypeScript and React application, built at author time into one file", "created": "2026-09-07", "outcome": "A reader opens the bundle on three goal-shaped surfaces instead of five record-type tabs, an engineer changes one surface by opening one typed React component, and the file that ships is still one self-contained HTML page that publishes as an Artifact unchanged.", "done_when": ["the viewer opens on a Work board that lists every design with its stage, epic progress, and which records exist, and a lane filter narrows it to the work that needs a decision, a build, or a review", "a design opens through six lenses (intent, problem and solution, architecture, risks and verdict, build, pull requests), and the intent lens leads with the intent prose and ends with the done-when list as bullet points", "a lens with no record is disabled rather than empty, and a backlog design that carries only goal.json renders correctly, with its greyed lenses stated as the honest record state", "the Flight deck is its own surface, and it shows a pull request's four narration levels, its Mermaid diagrams, its scene art, its intent and assessment, and the joins that reach it", "plugins/artifact/viewer/index.html is produced by a Vite build from typed React sources under viewer/src/, and a test fails when the committed output does not equal a fresh build", "npm install and npm run build run only when an engineer changes the viewer, never at /plugin install and never in the browser", "export_artifact.py matches named markers the build emits on purpose, instead of incidental literals, and publishing a pull request still succeeds", "the five record-type tabs are gone, and every record they showed is reachable from one of the three surfaces", "the three items build-workflow-polish carried outside the viewer are delivered here: the design-to-implement handoff line, the slice-table column shape, and the missing commit step after an accepted slice", "a review comment reaches feedback-ledger.jsonl when the viewer is served with --allow-write, and the viewer never claims a comment will sync when nothing syncs", "a published Artifact marks comments read-only, collects them in the browser, and hands the reviewer one block to paste back into the ledger"], "abort_if": ["a byte-equal rebuild cannot be made reliable across machines, because a lockfile and a pinned Node version do not produce identical output, which would make the guard test flaky and the committed file untrustworthy", "the built single file plus its inlined data exceeds the 16 MiB Artifact budget for a normal pull request, and dropping audio does not recover it", "Claude Artifacts will not render a Mermaid block that React injects after page load, and a vendored Mermaid runtime pushes the published file over the same budget"], "min_work": {"derived_from": "6 districts, 5 colliding ADRs (0001, 0018, 0019, 0020, 0022), 1 bounded context (cobuilder-packaging), 1 boundary rule on the install surface, 4899 measured viewer lines, 1 working prototype built in this session", "alternatives_explored": 5, "boundary_rules_checked": true, "challenge_stage_run": true}, "limits": {"warn_after_rounds": 3, "cutoff_rounds": 6}, "epics": [{"id": "E1", "slug": "exporter-seam", "branch": null, "pr": null, "state": "planned", "outcome": "export_artifact.py matches named markers, and a test proves a publish still works after the markers move", "note": "The exporter rewrites the viewer by verbatim string replacement today and hard-errors when a literal moves. A bundled build moves every literal, so this seam must become explicit before any build lands."}, {"id": "E2", "slug": "build-pipeline", "branch": null, "pr": null, "state": "planned", "outcome": "a publish spike answers the three platform unknowns, then npm run build produces the committed index.html and a test rebuilds it and fails on any difference", "note": "Vite plus vite-plugin-singlefile, a lockfile, and a pinned Node version. This epic starts with a spike, at the engineer's direction: publish one throwaway bundled page and measure the byte-equal rebuild across two machines, the size with React inlined, and whether a Claude Artifact renders a Mermaid block that React injects after page load. Two of the three abort conditions are settled by that spike, before five epics of work depend on the answer."}, {"id": "E3", "slug": "typed-data-layer", "branch": null, "pr": null, "state": "planned", "outcome": "one typed model reads window.STORY, window.ODYSSEY, window.DIFFS, window.ADRS, window.DESIGNS, window.DIAGRAMS and index.json, and the joins are resolved in one place", "note": "The viewer resolves joins by hand in each render path today. index.json already computed them. This epic makes the index the source and the types the contract."}, {"id": "E4", "slug": "work-surface", "branch": null, "pr": null, "state": "planned", "outcome": "the Work board and the seven design lenses render every design, including a backlog design with goal.json only", "note": "The prototype of 2026-09-07 is the reference for this surface."}, {"id": "E5", "slug": "flight-deck", "branch": null, "pr": null, "state": "planned", "outcome": "the Flight deck renders a pull request at parity with today's viewer, plus the joins rail", "note": "Parity covers the four levels, diagrams, scene art, narration audio, the diff, and the intent and assessment sheet."}, {"id": "E6", "slug": "reference-surface", "branch": null, "pr": null, "state": "planned", "outcome": "decisions and map coverage move to a Reference surface, and the five record-type tabs are removed", "note": "tests/test_viewer_modes.py asserts the five data-mode buttons. That test changes with this epic, and the change is the point, not a regression."}, {"id": "E7", "slug": "publish-parity", "branch": null, "pr": null, "state": "planned", "outcome": "a published Artifact of one pull request renders every surface, under the 16 MiB budget", "note": "Closes the loop on E1. Measures the real budget with React inlined, and settles the Mermaid question the third abort condition names."}, {"id": "E8", "slug": "workflow-polish-carryover", "branch": null, "pr": null, "state": "planned", "outcome": "the three non-viewer items from build-workflow-polish ship, so closing that design loses nothing", "note": "build-workflow-polish is superseded by this design at the engineer's direction. Its E4, the tab-based viewer layout, is absorbed by E4 and E5 here. Its other three epics are not viewer work and would be lost silently: E1 adds the pointer from design mode stage 7 to /implement:start, E2 states the six-column slice-table shape that shared/slice_table.py parses, and E3 commits an accepted slice without a second prompt. They are carried here so the supersede is safe."}, {"id": "E9", "slug": "feedback-path", "branch": null, "pr": null, "state": "planned", "outcome": "the served viewer files a comment to the ledger or says plainly that it did not, and a published Artifact collects comments and hands them back as one pasteable block, with anchors that survive a React re-render", "note": "The comment mechanism does not work today, and the engineer confirmed it on 2026-09-07. Three causes, all verified in the tree. First, LEDGER_AVAILABLE at viewer/index.html line 1399 tests only whether fetch exists in the browser, which is always true, so it never tells a reviewer that no ledger server is listening. Second, a failed POST falls back to localStorage and shows 'Will sync when server is reachable', although nothing syncs: no code reads that key back. Third, a published Artifact cannot reach any server, because the Artifact CSP blocks fetch, so every comment left where review actually happens is written to one browser's localStorage and lost. This epic also settles ADR-0019's anchoring under React, which owns the DOM the anchor walk uses. The transport is decided: the served viewer keeps POST /feedback under --allow-write, and the published Artifact marks comments read-only and exports them for paste-back through the copy-as-markdown path that already exists. The Artifact platform's own storage is rejected, because it would make the published page behave differently from the served one, which is the split ADR-0001 exists to prevent."}], "stage": "review", "supersedes": ["maintainable-viewer", "build-workflow-polish"], "adr": "ADR-0023", "adrs": ["ADR-0023", "ADR-0001", "ADR-0018", "ADR-0019", "ADR-0020"], "rounds": [{"n": 1, "changed": true, "feedback_class": "material"}, {"n": 2, "changed": true, "feedback_class": "material"}, {"n": 3, "changed": true, "feedback_class": "material"}, {"n": 4, "changed": true, "feedback_class": "material"}]}, "intent": {"problem": "The viewer slices the bundle by record type. Its five tabs mirror the five entity lists in index.json, so every real task crosses them. A reader who reviews pull request 11 reads its story, then ADR-0016 in a second tab, then the six plugin-split epics in a third, then their slice scores in a fourth, and holds the joins in their head although index.json already computed them. The reader does not arrive with a record type in mind. They arrive with one of three questions: is this decided, where has it got to, and was the change what we intended. Rebuilding the surfaces around those three questions means state-dependent rendering that the current file cannot carry. It is 4899 lines, one IIFE, with 45 innerHTML string blocks and no template layer.", "approach": "Author the viewer as TypeScript and React under plugins/artifact/viewer/src/, and compile it with Vite and vite-plugin-singlefile into the committed plugins/artifact/viewer/index.html. The build runs when an engineer changes the viewer, never at /plugin install and never in the browser. A test rebuilds from source and fails when the committed output differs. The application renders three surfaces: Work, Flight deck, and Reference. A design opens through six lenses, and the intent lens leads with the intent prose and ends with the done-when list as bullet points. One typed data layer reads the bundle globals and index.json, and resolves every join in one place.", "alternatives": [{"option": "Keep ADR-0020 as decided: ordered parts under viewer/src/, concatenated by build_viewer.py, plain JavaScript", "rejected_because": "It fixes file size and fixes nothing about state. The three surfaces need a design record, a lens, a level, a filter, and a selection to compose, and concatenation of ordered parts still leaves 45 innerHTML blocks re-rendering by hand. It also cannot type the joins, which is where the current viewer's real defects sit. The engineer chose the React target after this option was argued."}, {"option": "TypeScript with no framework, bundled by esbuild, using template literals and a small render loop", "rejected_because": "It answers the typing objection and keeps the toolchain small, and it still leaves every list re-render hand-written. The prototype is the evidence: the lens and level switching is where the manual innerHTML cost concentrates, and that is exactly the part a component model removes."}, {"option": "Preact and preact-compat instead of React, same Vite pipeline", "rejected_because": "It wins on bundle size, about 4 KB against about 45 KB compressed, and the 16 MiB Artifact budget is dominated by base64 audio and images, not by the runtime. The engineer asked for React. Preact stays available as a drop-in lever if E7 measures the budget as tight."}, {"option": "Two artefacts: a React application served locally by /artifact:view, and a reduced single file for publishing", "rejected_because": "It splits the truth. Two renderers drift, and a reader who publishes an Artifact would review a different page from the one they served. ADR-0001 exists because the published file and the served file are the same file."}, {"option": "Serve the viewer from a small local web application, and drop the single-file constraint", "rejected_because": "ADR-0001 forbids it. A published Artifact is one file under a CSP that blocks every external request, and /artifact:publish is a shipped mode with two recorded publications."}], "authorship": "agent-assisted", "captured": "2026-09-07", "design_name": "react-viewer", "out_of_scope": ["any change to what the generation scripts write into the bundle", "a new record type, a new join, or a schema version bump", "the open pull request gap that inflight-record-store owns", "the diff view's own rendering, which is ported as it stands", "publishing a Notion target, which stays a reserved flag value"], "reviewer_focus": ["E1 ordering: the exporter seam must land before any bundled output, or publishing breaks silently", "the spike inside E2, which settles two of the three abort conditions before the rest of the work depends on them", "whether the six lenses read plainly, in particular the lens named risks and verdict, which the engineer found unclear when it was named assessment", "ADR-0019's comment anchors, which remain unsettled"], "risks": ["a contributor now needs Node and npm to change the viewer, which the repository has never required, and the engineer accepted this cost on 2026-09-07", "a committed build artifact goes stale the moment somebody edits the output instead of the source", "a byte-equal rebuild depends on a pinned toolchain, and a version drift makes the guard test fail for the wrong reason", "the React runtime is inlined into every published Artifact, which spends part of the 16 MiB budget", "the rewrite is large enough to stall between the old viewer and the new one", "closing build-workflow-polish loses three non-viewer fixes unless E8 carries them, which is why E8 exists"], "source": "design", "testing": "Not built yet. The prototype of 2026-09-07 exercised the three surfaces against the real self-bundle, and it is the acceptance reference for E4 and E5. E2 carries the byte-equal rebuild test. E7 measures a real published Artifact against the budget.", "unknowns": ["whether Claude Artifacts renders a Mermaid block that React injects after page load, or whether a vendored runtime is needed", "whether Vite plus vite-plugin-singlefile produces a byte-identical file across two machines with the same lockfile and Node version", "how large the inlined React runtime makes a published pull request that also carries scene art", "whether the viewer's anchored-comments ledger (ADR-0019) survives a React re-render, since it computes anchors from the live DOM. The engineer has not decided this yet"], "why_now": "Two forces meet. ADR-0020 already decided that the viewer must stop being one hand-edited file, and it is decided and not executed, so no work is thrown away by choosing the target shape now. A prototype built on 2026-09-07 proved the three-surface shape against the real bundle, and it also proved the cost: about 700 lines of hand-written render functions and manual innerHTML for a reduced version of the same idea. The next surface is cheaper to build in a typed component model than to retrofit later."}, "assessment": {"verdict": "proceed", "findings": [{"kind": "prediction", "id": "F1", "severity": "low", "title": "Resolved in round 2: ADR-0023 supersedes ADR-0020 outright", "detail": "ADR-0020 rejected a bundler because it 'adds a Node toolchain to a repository of prose, Python scripts, and one HTML file'. That statement stays true, and the engineer accepted the cost on 2026-09-07 and required React and TypeScript. ADR-0023 therefore supersedes ADR-0020, and maintainable-viewer moves to stage superseded. The store carries one live answer.", "cites": "ADR-0020, docs/architecture/designs/maintainable-viewer/goal.json"}, {"kind": "prediction", "id": "F2", "severity": "high", "title": "The exporter seam breaks on the first bundled build unless E1 lands first", "detail": "export_artifact.py rewrites the viewer by verbatim string replacement, and it hard-errors when a literal is not found. A bundled and minified build moves or renames every literal it matches. Any ordering that lands the build before the seam leaves publishing broken until somebody publishes, which is the exact silent failure ADR-0020's forces already recorded. E1 is correctly first, and it must not be reordered.", "cites": "ADR-0020 forces, plugins/artifact/scripts/export_artifact.py"}, {"kind": "prediction", "id": "F3", "severity": "high", "title": "The comment path is broken today, and a React rewrite must fix it rather than port it", "detail": "ADR-0019 computes a comment anchor from the live DOM at annotation time. React replaces nodes on state change, so the anchor strategy needs a decision. That was the original finding. Round 3 makes it larger: the path does not work today either. viewer/index.html line 1399 sets LEDGER_AVAILABLE by testing whether fetch exists, which is always true, so a failed POST is indistinguishable from no server. The fallback writes to localStorage and shows 'Will sync when server is reachable', and nothing reads that key back. A published Artifact cannot POST at all under its CSP. E9 owns the fix.", "cites": "ADR-0019, plugins/artifact/viewer/index.html:1399, plugins/artifact/scripts/serve_bundle.py, ADR-0001"}, {"kind": "prediction", "id": "F4", "severity": "low", "title": "Resolved in round 2: a spike inside E2 moves the veto to the front", "detail": "Three of the four unknowns are publishing questions, and two of the three abort conditions depend on them. E2 now starts with a spike that publishes one throwaway bundled page and measures the byte-equal rebuild, the size with React inlined, and post-load Mermaid rendering. The evidence arrives before five epics depend on it.", "cites": "ADR-0001, docs/architecture/designs/react-viewer/goal.json abort_if"}, {"kind": "prediction", "id": "F5", "severity": "low", "title": "The install-surface rule is not violated by this design", "detail": "The packaging context's public interface names commands, skills, and script constants. It does not name a build step, and /plugin install runs no build in either the current or the proposed shape. A Node toolchain that runs only on a maintainer's machine, and only when the viewer changes, sits outside the install surface. The rule of no agents, no hooks, and no MCP servers is also untouched.", "cites": "docs/architecture/contexts/cobuilder-packaging/boundary.yaml, ADR-0016"}, {"kind": "prediction", "id": "F6", "severity": "low", "title": "Not a duplicate of any existing decision, and it absorbs one backlog design", "detail": "No ADR in the store of 22 decides a viewer framework. ADR-0018 decides the record index this design reads, ADR-0019 decides the ledger it must preserve, and ADR-0022 covers gate documents it renders. The only collision is ADR-0020 and its maintainable-viewer design, which F1 covers. build-workflow-polish also names a viewer tab layout in its outcome, and that item should be re-read once this design settles, because the layout it borrows may no longer exist.", "cites": "ADR-0018, ADR-0019, ADR-0022, docs/architecture/designs/build-workflow-polish/goal.json"}, {"kind": "prediction", "id": "F7", "severity": "medium", "title": "Closing build-workflow-polish loses three non-viewer fixes unless E8 carries them", "detail": "build-workflow-polish carries four epics, and only E4 is viewer work. E1 adds the missing pointer from design mode stage 7 to /implement:start, E2 states the six-column slice-table shape that shared/slice_table.py parses, and E3 commits an accepted slice without a second prompt. None of the three belongs to a viewer design. The engineer directed that the design be closed, so E8 carries the three items into this design. Without E8, the supersede is a silent deletion.", "cites": "docs/architecture/designs/build-workflow-polish/goal.json, shared/slice_table.py"}, {"kind": "prediction", "id": "F8", "severity": "low", "title": "Resolved in round 4: read-only plus paste-back for a published Artifact", "detail": "The engineer chose two of the three options on 2026-09-07. The served viewer keeps POST /feedback under --allow-write. The published Artifact marks comments read-only, collects them in the browser, and hands the reviewer one block to paste back. The platform-storage option is rejected, because the published page would then behave differently from the served page. Both surfaces now write to the same ledger, one directly and one through a paste.", "cites": "ADR-0001, ADR-0019, plugins/artifact/scripts/serve_bundle.py"}], "boundary_checks": [{"rule": "no plugin reads another plugin's files", "result": "pass", "detail": "Every path this design touches sits inside plugins/artifact/ or shared/."}, {"rule": "no agents, hooks, or MCP servers in the install surface", "result": "pass", "detail": "The build is a maintainer step. Nothing new installs."}, {"rule": "ADR-0001: the published viewer is one self-contained file", "result": "pass", "detail": "vite-plugin-singlefile inlines every asset. The output stays one file."}], "constraint_introduced": "plugins/artifact/viewer/index.html is a build output compiled from TypeScript and React sources under plugins/artifact/viewer/src/. An engineer edits a source file, never the output. A test rebuilds from source and fails when the committed output differs. The build never runs at install time and never in the browser.", "drift": [], "regret_risk": "If this design ships as written, the team lives with a Node toolchain in a repository that had none, and with a committed build artifact that only stays true while every engineer remembers to run the build. The guard test makes forgetting loud, so the durable regret is not staleness. It is reach: a contributor who could previously fix a viewer bug with a text editor now needs npm install first. That cost is paid on every future viewer change, and it is the one cost no epic in this design removes.", "risk_tier": "sensitive", "stage": "design", "summary": "The three-surface shape is grounded, and a working prototype against the real bundle is stronger evidence than most designs carry at this stage. Round 2 closed both reasons the first assessment held back a clean verdict. The engineer directed that ADR-0023 supersedes ADR-0020 outright, so the store carries one live answer rather than two. The engineer also directed a spike inside E2, which moves the three unmeasured platform questions in front of the work that depends on them. One risk is now created rather than removed: closing build-workflow-polish would drop three fixes that are not viewer work, and E8 exists to carry them."}, "narrative": {"landscape": {"tagline": "The viewer shows five tables. A reader asks three questions. This design rebuilds it around the questions, and changes what the file is made of to make that affordable.", "narration": "The bundle viewer grew one tab per entity list. Designs, pull requests, decisions, contexts, and builds each got a place, and the shape was honest, because it matched what build_index.py emits. It is also why every real task crosses four tabs. A reader reviewing a pull request wants its story, the decisions it cites, the epics it carries, and the slice scores behind them. The index already joins all four. The viewer makes the reader do the join again by hand. Meanwhile the file that would have to change is 4899 lines in one function scope, with 45 places that build HTML from strings and no template anywhere. ADR-0020 saw that in August and decided to break the file into parts. That decision is recorded and unexecuted, so nothing is lost by asking a harder question now: not how to split this file, but what the file should be."}, "problem_solution": {"problem": "The viewer slices by record type, so a reader holds joins in their head that index.json already computed. Rebuilding it around three goal-shaped surfaces needs state-dependent rendering that a single hand-edited file cannot carry.", "solution": "Author the viewer as TypeScript and React, compile it with Vite into the same committed single file, and render three surfaces: Work, Flight deck, and Reference.", "narration": "The three surfaces come from three questions. Is this decided, and does the tree still match the decision. Where has this design got to, and what blocks the next slice. What does this pull request change, and was it what we intended. The Work board answers the first two: every design in one list, with its stage, its epic progress, and which records exist, and four lanes that filter it to what needs a decision, what is ready to build, what is in review, and what shipped. Opening a design gives seven lenses over the same record, and a lens with no data is disabled rather than empty, so a backlog design that carries only goal.json reads as a deliberate state rather than a loading failure. The Flight deck answers the third, as its own surface, because reviewing a pull request is a different posture from planning work. Reference holds what hangs off no single design: the decisions and the map coverage.", "beats": [{"kind": "problem", "text": "Five tabs mirror five entity lists, so a four-tab journey is the normal case for one review."}, {"kind": "constraint", "text": "ADR-0001 fixes the output: one self-contained file, under a CSP that blocks every external request."}, {"kind": "constraint", "text": "/plugin install runs no build, so whatever the plugin ships is what runs."}, {"kind": "decision", "text": "Keep the output. Change the source. TypeScript and React under viewer/src/, compiled by Vite into the committed index.html."}, {"kind": "decision", "text": "Three surfaces replace five tabs, and the record types become filters and lenses underneath them."}, {"kind": "risk", "text": "A contributor now needs Node to change the viewer. That cost is real and no epic removes it."}], "alternatives": [{"option": "Ordered parts concatenated by a Python script, as ADR-0020 decided", "rejected_because": "It fixes file size and leaves every list re-render hand-written and untyped."}, {"option": "TypeScript with no framework, bundled by esbuild", "rejected_because": "It types the joins and still leaves the lens and level switching as manual innerHTML, which is where the cost concentrates."}, {"option": "Preact instead of React", "rejected_because": "It wins on bundle size, and the budget is dominated by audio and images. It stays available as a lever if the measurement in E7 comes back tight."}, {"option": "A served application plus a reduced published file", "rejected_because": "Two renderers drift, and a reader would review a different page from the one they served."}]}, "architecture": {"narration": "One typed data layer sits between the bundle and the surfaces. It reads the globals the bundle already sets, and index.json, and it resolves every join once. The surfaces read that model and nothing else, which is the property the current viewer lacks: today a join is re-derived inside each render path. The build is the other half. Vite compiles the sources and vite-plugin-singlefile inlines every asset into one file, which is committed to the plugin, because install runs no build. A test rebuilds from source and fails when the committed file differs, so an edit to the output cannot survive review. Two existing consumers read that file and both keep working: migrate_bundle.py copies it into every bundle unconditionally, and export_artifact.py rewrites it for publishing. The exporter is the fragile one, because it matches literal strings that a bundler moves, so it is the first epic and not the last.", "beats": [{"kind": "component", "text": "viewer/src/data: typed readers over STORY, ODYSSEY, DIFFS, ADRS, DESIGNS, DIAGRAMS, and index.json, with the joins resolved once."}, {"kind": "component", "text": "viewer/src/surfaces: Work, Flight deck, and Reference, each reading the model and owning its own routing state."}, {"kind": "component", "text": "vite.config.ts with vite-plugin-singlefile, a lockfile, and a pinned Node version."}, {"kind": "seam", "text": "export_artifact.py matches named markers the build emits on purpose, instead of incidental literals."}, {"kind": "seam", "text": "migrate_bundle.py is unchanged: it still copies the plugin's built viewer into every bundle, unconditionally."}, {"kind": "guard", "text": "A test rebuilds from source and compares against the committed output."}]}}, "diagrams": {"1": "C4Container\n    title react-viewer - the viewer becomes a built application, and the bundle contract does not change\n\n    Person(reader, \"Reader\", \"Reviews designs, builds, and pull requests\")\n    Person(engineer, \"Viewer engineer\", \"Changes one surface\")\n\n    Container_Boundary(plugin, \"plugins/artifact/\") {\n        Container(src, \"viewer/src/\", \"TypeScript + React\", \"Typed data layer, three surfaces, one component tree\")\n        Container(vite, \"vite.config.ts + package-lock.json\", \"Vite + vite-plugin-singlefile\", \"Author-time build, pinned Node\")\n        Container(out, \"viewer/index.html\", \"committed build output\", \"One self-contained file. Nobody edits it by hand\")\n        Container(export, \"scripts/export_artifact.py\", \"PEP 723 script\", \"Inlines data, rewrites named markers, publishes one PR\")\n    }\n\n    Container_Boundary(shared, \"shared/\") {\n        Container(migrate, \"migrate_bundle.py\", \"PEP 723 script\", \"Copies the built viewer into every bundle, unconditionally\")\n        Container(index, \"build_index.py\", \"PEP 723 script\", \"Writes data/index.json with every join resolved\")\n    }\n\n    Container_Boundary(bundle, \".cobuilder-architect/self/\") {\n        ContainerDb(data, \"data/\", \"JS globals + index.json\", \"STORY, ODYSSEY, DIFFS, ADRS, DESIGNS, DIAGRAMS\")\n        Container(copy, \"viewer/index.html\", \"bundle copy\", \"Refreshed on every mode run\")\n    }\n\n    Rel(engineer, src, \"edits a surface or the data layer\")\n    Rel(src, vite, \"compiled by\")\n    Rel(vite, out, \"writes\")\n    Rel(migrate, out, \"reads\")\n    Rel(migrate, copy, \"overwrites\")\n    Rel(export, out, \"reads verbatim, rewrites markers\")\n    Rel(index, data, \"writes index.json\")\n    Rel(copy, data, \"reads at page load\")\n    Rel(reader, copy, \"opens three surfaces\")\n", "2": "sequenceDiagram\n    autonumber\n    actor E as Viewer engineer\n    participant SRC as viewer/src/*.tsx\n    participant VITE as npm run build\n    participant OUT as viewer/index.html\n    participant TEST as tests/test_viewer_build.py\n    participant MIG as migrate_bundle.py\n    participant EXP as export_artifact.py\n\n    E->>SRC: change one surface component\n    E->>VITE: npm run build\n    VITE->>OUT: write one self-contained file\n    E->>TEST: run the suite\n    TEST->>VITE: rebuild into a temporary directory\n    TEST-->>E: fail when the committed file differs\n    Note over TEST,OUT: The guard that stops anyone editing the output\n\n    E->>MIG: run any mode against a bundle\n    MIG->>OUT: read the plugin's built viewer\n    MIG->>MIG: overwrite the bundle copy, unconditionally\n\n    E->>EXP: /artifact:publish --pr 11\n    EXP->>OUT: read verbatim\n    EXP->>EXP: match named markers, inline STORY/DIFFS/ADRS/DIAGRAMS\n    alt result over 16 MiB\n        EXP->>EXP: retry at a lower tier, then drop audio\n    end\n    EXP-->>E: one publishable file\n", "3": "classDiagram\n    class BundleModel {\n        +designs: Design[]\n        +pullRequests: PullRequest[]\n        +adrs: Adr[]\n        +districts: District[]\n        +load(globals, index) BundleModel\n        +designById(id) Design\n        +prByNumber(n) PullRequest\n    }\n    class Design {\n        +id: string\n        +stage: Stage\n        +outcome: string\n        +goal: Goal\n        +intent: Intent | null\n        +narrative: Narrative | null\n        +assessment: Assessment | null\n        +epics: Epic[]\n        +adrs: AdrRef[]\n        +lane() Lane\n        +hasLens(lens) boolean\n    }\n    class Epic {\n        +id: string\n        +state: EpicState\n        +pr: number | null\n        +slices: Slice[]\n    }\n    class PullRequest {\n        +pr: number\n        +levels: Record~LevelKey, Level~\n        +diagrams: Record~string, string~\n        +intent: Intent | null\n        +assessment: Assessment | null\n        +joins: PrJoins\n    }\n    class WorkSurface {\n        +filter: Lane | null\n        +selected: string | null\n        +lens: LensKey\n    }\n    class FlightDeckSurface {\n        +selected: number\n        +level: LevelKey\n    }\n    class ReferenceSurface {\n        +sort: string\n    }\n    BundleModel \"1\" *-- \"many\" Design\n    BundleModel \"1\" *-- \"many\" PullRequest\n    Design \"1\" *-- \"many\" Epic\n    Epic \"1\" *-- \"many\" Slice\n    WorkSurface ..> BundleModel : reads\n    FlightDeckSurface ..> BundleModel : reads\n    ReferenceSurface ..> BundleModel : reads\n    Epic --> PullRequest : epic_to_pull_request\n"}, "pr_draft": "# The viewer becomes three goal-shaped surfaces, built from TypeScript and React\n\n## What this changes\n\nThe bundle viewer stops slicing by record type. Its five tabs (Designs, Pull\nrequests, Decisions, Contexts, Builds) become three surfaces:\n\n| Surface | The question it answers |\n|---|---|\n| Work | Is this decided, and where has it got to? |\n| Flight deck | What does this pull request change, and was it intended? |\n| Reference | What decisions and map coverage exist outside any one design? |\n\nThe record types do not disappear. They become lenses and filters underneath\nthe surfaces, and the joins that `data/index.json` already computes are\nrendered together instead of rebuilt by the reader across four tabs.\n\n## Why the source language changes too\n\n`plugins/artifact/viewer/index.html` is 4899 lines in one function scope, with\n45 `innerHTML` string blocks and no template layer. The three surfaces compose\nfive pieces of state at once. That is a component problem, not a file-size\nproblem.\n\nThe output does not change shape. Vite and `vite-plugin-singlefile` compile the\nsources into the same committed, self-contained `index.html`, so ADR-0001 holds\nand `/artifact:publish` keeps working.\n\nThis supersedes ADR-0020, which decided a Python concatenation of ordered parts\nand was never executed.\n\n## The cost, stated plainly\n\nA contributor now needs Node and npm to change the viewer. This repository has\nnever required either. No epic removes that cost.\n\n## How it lands\n\n| Epic | Outcome |\n|---|---|\n| E1 | `export_artifact.py` matches named markers, not incidental literals |\n| E2 | `npm run build` produces the committed file, and a test fails on any difference |\n| E3 | One typed data layer over the bundle globals and `index.json` |\n| E4 | The Work board and the seven design lenses |\n| E5 | The Flight deck, at parity with today's viewer |\n| E6 | The Reference surface, and the five tabs are removed |\n| E7 | A published Artifact renders every surface, under the 16 MiB budget |\n\nE1 is first on purpose. The exporter rewrites the viewer by verbatim string\nreplacement and hard-errors when a literal moves. A bundled build moves every\none of them.\n\n## What reviewers should look at\n\n1. The Node toolchain decision, which reverses one of ADR-0020's four rejected\n   options.\n2. The E1 ordering.\n3. Whether seven lenses is one too many.\n4. ADR-0019's comment anchors, which are computed from the live DOM that React\n   now owns.\n\n## Not in scope\n\nNo change to what the generation scripts write. No new record type, join, or\nschema version. The open pull request gap stays with `inflight-record-store`.\n"}, "ubiquitous-language": {"goal": {"name": "ubiquitous-language", "title": "A mandated ubiquitous language across the plugin family", "created": "2026-08-25", "outcome": "One term means one thing across every plugin, skill, design, and ADR in the repo, and a new or colliding term cannot reach a merged pull request undetected.", "done_when": [], "abort_if": ["a first mechanical check of an existing term set produces mostly false positives, showing that a script cannot tell a real term from ordinary prose", "design authors route around the language stage on three or more designs in a row, showing that enforcement is worked around rather than followed"], "min_work": {"derived_from": "A case-insensitive grep for ubiquitous|domain-driven|bounded context|aggregate|domain event|glossary|ddd returns zero hits in plugins/cobuilder-architect/skills/architecture/references/design-mode.md and zero hits in plugins/cobuilder-implement/skills/implement/SKILL.md. plugins/cobuilder-architect/skills/architecture/references/corpus/principles/ddd/ holds 11 files, loaded by design mode's Ground stage and by review mode, but nothing checks the result. architecture-documentation.md section 3 requires a context canvas to carry a ubiquitous language of 5 to 15 terms that disambiguates homonyms shared with other contexts, and describe mode obeys it. docs/architecture/contexts/cobuilder-packaging/canvas.md section 3 defines Skill as five skills, architecture, odyssey, mermaid, ste-writing, and collaborate-with-user, and three of those five names are now wrong. Its boundary.yaml public_interface still lists commands/submit.md and commands/explore-design.md, both deleted, and scripts/_bundle_meta, which moved to shared/. The canvas also states that Skill and command carry the same meaning across the whole repo, with no homonym conflict against CLAUDE.md's vocabulary table, and that claim is now false because CLAUDE.md's table and the canvas section do not know about each other. CLAUDE.md itself records the lesson: a process step with no mechanical consumer gets skipped, however well it is documented, citing Gate 4b, which ran for zero of five multi-slice epics before it gained a mechanical check.", "challenge_stage_run": false, "note": "Stages 2 through 7 are deliberately deferred. This design is a backlog entry, not an approved design. It carries no intent.json, narrative.json, assessment.json, or diagrams, and it must not be implemented until design mode runs to completion."}, "limits": {"warn_after_rounds": 3, "cutoff_rounds": 6}, "epics": [{"id": "E1", "branch": null, "pr": null, "state": "planned", "note": "One language record, and it is the tracer bullet. docs/architecture/language.md becomes the single source of truth for a term, its owning context, its meaning, and what it must not be confused with. It is seeded from CLAUDE.md's existing Vocabulary table and from cobuilder-packaging's canvas section 3. shared/build_index.py projects it into the record index, so the viewer can render it. This epic is independently shippable and does not depend on E2 through E5."}, {"id": "E2", "branch": null, "pr": null, "state": "planned", "note": "Design mode gains a language stage. A design that introduces a new term must declare it or reuse an existing entry from the language record. A collision with an existing term becomes a challenge-stage finding. This fits design mode's existing no-citation-no-challenge rule, because the language record gives the challenge stage something concrete to cite."}, {"id": "E3", "branch": null, "pr": null, "state": "planned", "note": "The mechanical consumer, in cobuilder-implement. A Gate 4b technical solution design that names a concept absent from the language record fails the gate. This epic is what stops the whole program from rotting the way canvas section 3 did. E1 and E2 without E3 are documentation waiting to go stale."}, {"id": "E4", "branch": null, "pr": null, "state": "planned", "note": "A verifier that exits non-zero. A script finds a term used in a design or an ADR and absent from the language record, and fails the check. It is modeled on plugins/cobuilder-implement/scripts/verify_gate.py, which exits non-zero on any failed Gate 4 sub-step. The honest open question is that deciding what counts as a term mechanically, rather than by judgement, is the hard part of this epic and may need its own exploration."}, {"id": "E5", "branch": null, "pr": null, "state": "planned", "note": "Repair the existing drift. Refresh cobuilder-packaging's canvas section 3 and its boundary.yaml public_interface against the shipped five-plugin tree, delete the now-false homonym comment, and reconcile the two glossaries into E1's record."}], "stage": "backlog", "supersedes": null, "adr": null, "adrs": [], "rounds": []}}};
